const INDEX_HTML = "<!DOCTYPE html>\n<html lang=\"ja\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<meta name=\"theme-color\" content=\"#7fffb2\">\n<link rel=\"manifest\" href=\"/manifest.json\">\n<title>YT Watcher</title>\n<style>\n:root{--bg:#0a0a0f;--bg2:#111118;--bg3:#1a1a24;--border:#2a2a38;--accent:#7fffb2;--accent2:#ff7f50;--accent3:#7fb8ff;--text:#e0e0e8;--muted:#666678;--danger:#ff4466;--r:6px;--bar:28px;--tab:34px}\n*{box-sizing:border-box;margin:0;padding:0;-webkit-tap-highlight-color:transparent}\nhtml,body{height:100%;background:var(--bg);color:var(--text);font-family:'Space Mono',monospace;font-size:13px;overflow:hidden}\n::-webkit-scrollbar{width:4px;height:4px}::-webkit-scrollbar-thumb{background:var(--border);border-radius:2px}\n#bar{position:fixed;top:0;left:0;right:0;height:var(--bar);background:rgba(10,10,15,.95);backdrop-filter:blur(12px);border-bottom:1px solid var(--border);display:flex;align-items:center;z-index:200}\n.dots{display:flex;gap:6px;padding:0 12px}.dot{width:11px;height:11px;border-radius:50%}\n.dot.r{background:#ff5f57}.dot.y{background:#ffbd2e}.dot.g{background:#28c840}\n.bar-title{padding:0 8px;font-weight:bold;color:var(--accent);font-size:12px}.spacer{flex:1}\n.bar-right{display:flex;align-items:center;gap:5px;padding:0 8px}\n.badge{font-size:10px;padding:1px 6px;border-radius:8px;background:var(--accent);color:#000;font-weight:bold;cursor:pointer;white-space:nowrap}\n.badge.off{background:var(--muted)}.badge.warn{background:var(--accent2)}\n.bar-btn{background:none;border:none;color:var(--muted);cursor:pointer;padding:3px 6px;font-size:11px;border-radius:4px;font-family:inherit}\n.bar-btn:hover{background:var(--bg3);color:var(--text)}\n#tabbar{position:fixed;top:var(--bar);left:0;right:0;height:var(--tab);background:var(--bg2);border-bottom:1px solid var(--border);display:flex;align-items:flex-end;padding:0 4px;overflow-x:auto;overflow-y:hidden;z-index:190;gap:1px}\n#tabbar::-webkit-scrollbar{height:2px}\n.tab-item{flex-shrink:0;height:28px;min-width:120px;max-width:200px;display:flex;align-items:center;gap:5px;padding:0 8px;background:var(--bg3);border:1px solid var(--border);border-bottom:none;border-radius:6px 6px 0 0;cursor:pointer;position:relative;user-select:none}\n.tab-item.active{background:var(--bg);border-bottom-color:var(--bg)}\n.tab-item.active::after{content:'';position:absolute;bottom:-1px;left:0;right:0;height:1px;background:var(--bg)}\n.tab-icon{width:13px;height:13px;flex-shrink:0;opacity:.5;fill:currentColor}.tab-item.active .tab-icon{opacity:1}\n.tab-name{flex:1;font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:var(--muted)}.tab-item.active .tab-name{color:var(--text)}\n.tab-item.pinned{min-width:90px;max-width:120px}\n.tab-close{width:16px;height:16px;border-radius:50%;border:none;background:transparent;color:var(--muted);cursor:pointer;font-size:11px;flex-shrink:0;padding:0;display:flex;align-items:center;justify-content:center}\n.tab-close:hover{background:rgba(255,68,102,.2);color:var(--danger)}\n.tab-add{flex-shrink:0;width:28px;height:28px;border:none;background:transparent;color:var(--muted);cursor:pointer;font-size:18px;border-radius:6px 6px 0 0;display:flex;align-items:center;justify-content:center;margin-left:2px}\n.tab-add:hover{background:var(--bg3);color:var(--accent)}\n#app{position:fixed;top:62px;left:0;right:0;bottom:0;overflow:hidden}\n.pane{position:absolute;inset:0;overflow-y:auto;display:none;padding:12px}.pane.active{display:block}\ninput[type=text],input[type=date],input[type=time],input[type=url],textarea,select{background:var(--bg3);border:1px solid var(--border);border-radius:var(--r);color:var(--text);padding:7px 10px;font-family:inherit;font-size:12px;outline:none;width:100%}\ninput:focus,textarea:focus,select:focus{border-color:var(--accent)}\nselect option{background:var(--bg2)}\nbutton{padding:7px 14px;border-radius:var(--r);border:none;cursor:pointer;font-family:inherit;font-size:12px;transition:all .15s}\n.btn-accent{background:var(--accent);color:#000;font-weight:bold}.btn-accent:hover{filter:brightness(1.1)}\n.btn-outline{background:transparent;border:1px solid var(--border);color:var(--text)}.btn-outline:hover{border-color:var(--accent);color:var(--accent)}\n.btn-sm{padding:4px 10px;font-size:10px}\n.btn-danger{background:transparent;border:1px solid var(--danger);color:var(--danger)}.btn-danger:hover{background:var(--danger);color:#fff}\n.field{margin-bottom:10px}.field label{display:block;font-size:10px;color:var(--muted);margin-bottom:3px;text-transform:uppercase;letter-spacing:.06em}\n.errmsg{font-size:11px;color:var(--danger);margin-top:5px;display:none}\n.btn-row{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}\n.empty{text-align:center;padding:40px 20px;color:var(--muted);line-height:2;font-size:12px}\n.loading{text-align:center;padding:30px;color:var(--muted);font-size:12px}\n/* Playlist */\n.setup-box{max-width:480px;margin:30px auto;background:var(--bg2);border:1px solid var(--border);border-radius:var(--r);padding:20px}\n.setup-box h2{font-size:13px;color:var(--accent);margin-bottom:14px}\n.vid-header{display:flex;align-items:center;gap:8px;margin-bottom:10px;flex-wrap:wrap}\n.video-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:10px}\n.video-card{background:var(--bg2);border:1px solid var(--border);border-radius:var(--r);overflow:hidden;cursor:pointer;transition:border-color .15s}\n.video-card:hover{border-color:var(--accent)}\n.video-card img{width:100%;aspect-ratio:16/9;object-fit:cover;display:block;background:var(--bg3)}\n.vc-title{padding:8px;font-size:11px;line-height:1.4;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}\n/* Schedule */\n.sched-top{background:var(--bg2);border:1px solid var(--border);border-radius:var(--r);padding:10px;margin-bottom:10px}\n.sched-top-row{display:flex;align-items:center;gap:6px;flex-wrap:wrap}\n.sched-top-row h2{font-size:12px;color:var(--accent3);flex:1;display:flex;align-items:center;gap:5px}\n#sched-json{height:80px;resize:vertical;font-size:11px;margin-top:8px;display:none}\n#sched-json.open{display:block}\n/* Selection */\n#sel-toolbar{background:var(--bg3);border:1px solid var(--accent3);border-radius:var(--r);padding:7px 10px;margin-bottom:8px;display:none;align-items:center;gap:6px;flex-wrap:wrap}\n#sel-toolbar.show{display:flex}\n.sel-count{font-size:12px;color:var(--accent3);flex:1}\n.sel-btn{display:flex;align-items:center;gap:4px;padding:3px 9px;border-radius:var(--r);border:1px solid var(--border);cursor:pointer;font-size:11px;font-family:inherit;background:var(--bg2);color:var(--text)}\n.sel-btn:hover{border-color:var(--accent);color:var(--accent)}\n.sel-btn.danger{border-color:var(--danger);color:var(--danger)}.sel-btn.danger:hover{background:var(--danger);color:#fff}\n.sel-btn svg{width:11px;height:11px;fill:currentColor;flex-shrink:0}\n#mobile-sel-banner{display:none;background:rgba(127,184,255,.08);border:1px solid rgba(127,184,255,.25);border-radius:var(--r);padding:6px 10px;margin-bottom:8px;font-size:11px;color:var(--accent3);align-items:center;gap:6px}\n#mobile-sel-banner.show{display:flex}\n/* Calendar */\n#cal-wrap{display:none}#cal-wrap.show{display:block}\n.cal-nav{display:flex;align-items:center;gap:8px;margin-bottom:8px}\n.cal-nav h3{flex:1;text-align:center;font-size:13px}\n.cal-filter-row{display:flex;gap:6px;margin-bottom:8px;flex-wrap:wrap}\n.cal-filter-btn{padding:3px 10px;border-radius:999px;border:1px solid var(--border);font-size:10px;cursor:pointer;background:transparent;color:var(--muted);font-family:inherit}\n.cal-filter-btn.active{background:var(--accent3);border-color:var(--accent3);color:#000;font-weight:bold}\n.cal-grid{display:grid;grid-template-columns:repeat(7,1fr);gap:2px}\n.cal-head{text-align:center;font-size:10px;color:var(--muted);padding:3px 0}\n.cal-day{min-height:48px;background:var(--bg2);border:1px solid var(--border);border-radius:4px;padding:4px;cursor:pointer;position:relative}\n.cal-day:hover{border-color:var(--accent)}.cal-day.today{border-color:var(--accent)}\n.cal-day.other-month .cal-dn{opacity:.35}.cal-day.selected{border-color:var(--accent3);background:rgba(127,184,255,.06)}\n.cal-dn{font-size:11px;font-weight:bold;margin-bottom:3px}\n.cal-dots{display:flex;flex-wrap:wrap;gap:2px}\n.cal-dot{width:6px;height:6px;border-radius:50%}\n.cal-events-box{background:var(--bg2);border:1px solid var(--border);border-radius:var(--r);padding:10px;margin-top:8px}\n.cal-events-box h4{font-size:11px;color:var(--accent3);margin-bottom:8px;display:flex;align-items:center;gap:6px}\n.cal-ev{border-radius:0 var(--r) var(--r) 0;padding:8px 10px;margin-bottom:6px;font-size:11px;border-left:3px solid var(--accent3)}\n.cal-ev-sub{font-weight:bold;display:flex;align-items:center;justify-content:space-between;gap:6px}\n.cal-ev-meta{color:var(--muted);font-size:10px;margin-top:2px}\n.cal-ev-actions{display:flex;gap:5px;margin-top:6px;flex-wrap:wrap;align-items:center}\n/* Cards */\n.sched-cards{display:flex;flex-direction:column;gap:7px}\n.s-card{background:var(--bg2);border:1px solid var(--border);border-radius:9px;display:flex;overflow:hidden;transition:border-color .15s,opacity .2s}\n.s-card.selected{border-color:var(--accent3);background:rgba(127,184,255,.05)}\n.s-card.notify-on{border-left:3px solid var(--accent3)}\n.s-card.completed{opacity:.35;filter:grayscale(.5)}\n.s-cb-col{display:flex;align-items:flex-start;padding:12px 3px 12px 9px;flex-shrink:0;cursor:pointer}\n.s-checkbox{width:15px;height:15px;border:1.5px solid var(--border);border-radius:4px;display:flex;align-items:center;justify-content:center;transition:all .15s}\n.s-card.selected .s-checkbox{background:var(--accent3);border-color:var(--accent3)}\n.s-checkbox svg{width:9px;height:9px;fill:#000;display:none}.s-card.selected .s-checkbox svg{display:block}\n.s-body{flex:1;padding:10px 10px 10px 4px;display:flex;flex-direction:column;gap:7px;min-width:0}\n.s-head{display:flex;justify-content:space-between;align-items:flex-start;gap:6px}\n.s-subject{font-size:15px;font-weight:bold}.s-unit{font-size:11px;color:var(--muted);margin-top:2px}\n.s-date{font-size:11px;color:var(--muted);display:flex;align-items:center;gap:4px}\n.s-time{font-size:11px;display:flex;align-items:center;gap:4px}\n.s-def{font-size:10px;color:var(--muted)}\n.s-badges{display:flex;gap:5px;flex-wrap:wrap;align-items:center}\n.s-rel{padding:2px 8px;border-radius:999px;font-size:10px;font-weight:bold}\n.s-rel.future{background:rgba(127,184,255,.12);color:var(--accent3);border:1px solid rgba(127,184,255,.2)}\n.s-rel.today{background:rgba(127,255,178,.1);color:var(--accent);border:1px solid rgba(127,255,178,.2)}\n.s-rel.past{background:rgba(255,68,102,.08);color:var(--danger);border:1px solid rgba(255,68,102,.15)}\n.s-status{padding:2px 8px;border-radius:999px;font-size:10px}\n.s-status.normal{background:rgba(127,184,255,.1);color:var(--accent3)}\n.s-status.h_class{background:rgba(255,200,50,.1);color:#ffcc33}\n.s-status.s_class{background:rgba(255,68,102,.1);color:var(--danger)}\n.tog-wrap{display:flex;align-items:center;gap:5px;font-size:11px;color:var(--muted);cursor:pointer}\n.tog{position:relative;width:36px;height:19px;display:inline-block;flex-shrink:0}\n.tog input{display:none}.tog-sl{position:absolute;inset:0;background:var(--border);border-radius:999px;transition:.2s}\n.tog-sl:before{content:'';position:absolute;width:13px;height:13px;left:3px;top:3px;background:#fff;border-radius:50%;transition:.2s}\n.tog input:checked+.tog-sl{background:var(--accent3)}.tog input:checked+.tog-sl:before{transform:translateX(17px)}\n.tog.done input:checked+.tog-sl{background:var(--accent)}\n.s-link-btn{padding:3px 9px;border-radius:var(--r);background:rgba(16,185,129,.1);border:1px solid rgba(16,185,129,.2);color:#10b981;cursor:pointer;font-size:10px;font-family:inherit;display:flex;align-items:center;gap:3px}\n.s-link-btn:hover{background:rgba(16,185,129,.2)}\n.s-link-btn svg{width:10px;height:10px;fill:currentColor}\n.s-divider{text-align:center;font-size:10px;color:var(--muted);padding:5px 0;border-top:1px solid var(--border);margin:3px 0}\n/* Panels */\n#notif-panel,#recent-panel{position:fixed;top:var(--bar);width:280px;bottom:0;background:var(--bg2);z-index:180;display:flex;flex-direction:column;transition:transform .25s}\n#notif-panel{right:0;border-left:1px solid var(--border);transform:translateX(100%)}\n#notif-panel.open{transform:translateX(0)}\n#recent-panel{left:0;border-right:1px solid var(--border);transform:translateX(-100%)}\n#recent-panel.open{transform:translateX(0)}\n.panel-header{padding:10px 14px;border-bottom:1px solid var(--border);display:flex;align-items:center;justify-content:space-between;font-size:10px;color:var(--muted);text-transform:uppercase;letter-spacing:.08em}\n.panel-list{flex:1;overflow-y:auto;padding:8px}\n.notif-item{background:var(--bg3);border:1px solid var(--border);border-radius:var(--r);padding:10px;margin-bottom:6px}\n.ni-title{font-weight:bold;color:var(--accent);font-size:11px;margin-bottom:2px}\n.ni-body{font-size:11px;color:var(--text);line-height:1.5}\n.ni-time{font-size:10px;color:var(--muted);margin-top:3px}\n.ni-link{display:inline-block;font-size:10px;color:var(--accent3);text-decoration:none;margin-top:3px}\n.recent-item{background:var(--bg3);border:1px solid var(--border);border-radius:var(--r);padding:10px;margin-bottom:6px;display:flex;align-items:center;gap:8px}\n.ri-info{flex:1;min-width:0}.ri-name{font-size:12px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.ri-pl{font-size:10px;color:var(--muted)}.ri-time{font-size:10px;color:var(--muted);margin-top:2px}\n/* Modals */\n.modal-bg{display:none;position:fixed;inset:0;background:rgba(0,0,0,.65);z-index:300;align-items:center;justify-content:center;padding:16px}\n.modal-bg.open{display:flex}\n.modal-box{background:var(--bg2);border:1px solid var(--border);border-radius:10px;padding:20px;width:420px;max-width:100%;max-height:90vh;overflow-y:auto}\n.modal-box h3{font-size:12px;color:var(--accent);margin-bottom:12px}\n.share-url{background:var(--bg3);border:1px solid var(--border);border-radius:var(--r);padding:8px 10px;font-size:10px;color:var(--muted);word-break:break-all;margin-bottom:8px;line-height:1.6;max-height:80px;overflow-y:auto;font-family:monospace}\n.sec{font-size:10px;color:var(--muted);text-transform:uppercase;letter-spacing:.08em;margin-bottom:6px}\n.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}\n</style>\n<link href=\"https://fonts.googleapis.com/css2?family=Space+Mono:wght@400;700&display=swap\" rel=\"stylesheet\">\n</head>\n<body>\n<div id=\"bar\">\n  <div class=\"dots\"><div class=\"dot r\"></div><div class=\"dot y\"></div><div class=\"dot g\"></div></div>\n  <span class=\"bar-title\">YT Watcher</span>\n  <div class=\"spacer\"></div>\n  <div class=\"bar-right\">\n    <button class=\"bar-btn\" onclick=\"toggleRecent()\">\u6700\u8fd1</button>\n    <button class=\"bar-btn\" onclick=\"openShare()\">\u5171\u6709</button>\n    <span class=\"badge off\" id=\"push-badge\" onclick=\"togglePush()\">PUSH OFF</span>\n    <span class=\"badge off\" id=\"notif-badge\" onclick=\"toggleNotifPanel()\">0\u4ef6</span>\n  </div>\n</div>\n\n<div id=\"tabbar\">\n  <div class=\"tab-item pinned\" id=\"online-tab\" onclick=\"switchToOnline()\">\n    <svg class=\"tab-icon\" viewBox=\"0 0 24 24\"><path d=\"M19 4h-1V2h-2v2H8V2H6v2H5c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2V6c0-1.1-.9-2-2-2zm0 16H5V9h14v11zM7 11h5v5H7z\"/></svg>\n    <span class=\"tab-name\">\u30aa\u30f3\u30e9\u30a4\u30f3</span>\n  </div>\n  <button class=\"tab-add\" onclick=\"addTab()\">+</button>\n</div>\n\n<div id=\"app\">\n  <div class=\"pane\" id=\"pane-online\">\n    <div class=\"sched-top\">\n      <div class=\"sched-top-row\">\n        <h2><svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"var(--accent3)\"><path d=\"M19 4h-1V2h-2v2H8V2H6v2H5c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2V6c0-1.1-.9-2-2-2zm0 16H5V9h14v11zM7 11h5v5H7z\"/></svg>\u30aa\u30f3\u30e9\u30a4\u30f3\u901a\u77e5</h2>\n        <button class=\"btn-outline btn-sm\" onclick=\"openAddEvent()\">\uff0b \u8ffd\u52a0</button>\n        <button class=\"btn-outline btn-sm\" onclick=\"toggleJsonArea()\">JSON\u8aad\u8fbc</button>\n        <button class=\"btn-outline btn-sm\" id=\"view-btn\" onclick=\"toggleView()\">\u30ab\u30ec\u30f3\u30c0\u30fc</button>\n        <button class=\"btn-outline btn-sm\" onclick=\"openSchedShare()\">\u5171\u6709</button>\n        <button class=\"btn-danger btn-sm\" onclick=\"clearSchedule()\">\u5168\u524a\u9664</button>\n      </div>\n      <textarea id=\"sched-json\" placeholder='{\"schedule\":[...]} \u307e\u305f\u306f schedule\u914d\u5217'></textarea>\n      <div id=\"sched-err\" class=\"errmsg\"></div>\n      <div id=\"sched-load-row\" style=\"display:none;margin-top:6px\" class=\"btn-row\">\n        <button class=\"btn-accent btn-sm\" onclick=\"loadScheduleJson()\">\u8aad\u307f\u8fbc\u3080</button>\n        <button class=\"btn-outline btn-sm\" onclick=\"toggleJsonArea()\">\u30ad\u30e3\u30f3\u30bb\u30eb</button>\n      </div>\n    </div>\n    <div id=\"mobile-sel-banner\">\n      <svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M19 3H5c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2V5c0-1.1-.9-2-2-2zm-9 14l-5-5 1.41-1.41L10 14.17l7.59-7.59L19 8l-9 9z\"/></svg>\n      <span id=\"mb-sel-txt\">\u9078\u629e\u30e2\u30fc\u30c9</span><div style=\"flex:1\"></div>\n      <button class=\"sel-btn danger\" id=\"mb-del-btn\" style=\"display:none\" onclick=\"showDeleteConfirm()\"><svg viewBox=\"0 0 24 24\"><path d=\"M6 19c0 1.1.9 2 2 2h8c1.1 0 2-.9 2-2V7H6v12zM19 4h-3.5l-1-1h-5l-1 1H5v2h14V4z\"/></svg>\u524a\u9664</button>\n      <button class=\"sel-btn\" onclick=\"exitSelectionMode()\"><svg viewBox=\"0 0 24 24\"><path d=\"M19 6.41L17.59 5 12 10.59 6.41 5 5 6.41 10.59 12 5 17.59 6.41 19 12 13.41 17.59 19 19 17.59 13.41 12z\"/></svg>\u7d42\u4e86</button>\n    </div>\n    <div id=\"sel-toolbar\">\n      <span class=\"sel-count\" id=\"sel-count-text\">0\u4ef6\u9078\u629e</span>\n      <button class=\"sel-btn\" onclick=\"selectAll()\"><svg viewBox=\"0 0 24 24\"><path d=\"M19 3H5c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2V5c0-1.1-.9-2-2-2zm-9 14l-5-5 1.41-1.41L10 14.17l7.59-7.59L19 8l-9 9z\"/></svg>\u5168\u9078\u629e</button>\n      <button class=\"sel-btn danger\" onclick=\"showDeleteConfirm()\"><svg viewBox=\"0 0 24 24\"><path d=\"M6 19c0 1.1.9 2 2 2h8c1.1 0 2-.9 2-2V7H6v12zM19 4h-3.5l-1-1h-5l-1 1H5v2h14V4z\"/></svg>\u524a\u9664</button>\n      <button class=\"sel-btn\" onclick=\"clearSelection()\"><svg viewBox=\"0 0 24 24\"><path d=\"M19 6.41L17.59 5 12 10.59 6.41 5 5 6.41 10.59 12 5 17.59 6.41 19 12 13.41 17.59 19 19 17.59 13.41 12z\"/></svg>\u89e3\u9664</button>\n    </div>\n    <!-- Calendar -->\n    <div id=\"cal-wrap\">\n      <div class=\"cal-nav\">\n        <button class=\"btn-outline btn-sm\" onclick=\"calMove(-1)\">&#8249;</button>\n        <h3 id=\"cal-title\"></h3>\n        <button class=\"btn-outline btn-sm\" onclick=\"calMove(1)\">&#8250;</button>\n      </div>\n      <div class=\"cal-filter-row\">\n        <button class=\"cal-filter-btn active\" id=\"filt-all\" onclick=\"setCalFilter('all')\">\u5168\u3066</button>\n        <button class=\"cal-filter-btn\" id=\"filt-notify\" onclick=\"setCalFilter('notify')\">\u901a\u77e5ON\u306e\u307f</button>\n        <button class=\"cal-filter-btn\" id=\"filt-future\" onclick=\"setCalFilter('future')\">\u672a\u6765\u306e\u307f</button>\n      </div>\n      <div class=\"cal-grid\" id=\"cal-grid\"></div>\n      <div id=\"cal-events\" style=\"display:none\"></div>\n    </div>\n    <!-- List -->\n    <div id=\"list-wrap\">\n      <div class=\"sched-cards\" id=\"sched-cards\"><div class=\"empty\">\u300c\uff0b \u8ffd\u52a0\u300d\u307e\u305f\u306fJSON\u3092\u8aad\u307f\u8fbc\u3093\u3067\u304f\u3060\u3055\u3044</div></div>\n    </div>\n  </div>\n</div>\n\n<!-- Panels -->\n<div id=\"notif-panel\">\n  <div class=\"panel-header\"><span>\u901a\u77e5\u30bb\u30f3\u30bf\u30fc</span><button class=\"btn-outline btn-sm\" onclick=\"clearNotifs()\">\u5168\u6d88\u53bb</button></div>\n  <div class=\"panel-list\" id=\"np-list\">\n    <div style=\"padding:8px\">\n      <button class=\"btn-outline btn-sm\" onclick=\"testLocalNotif()\" style=\"width:100%;margin-bottom:6px\">\u901a\u77e5\u30c6\u30b9\u30c8</button>\n      <div id=\"push-debug\" style=\"font-size:10px;color:var(--muted);line-height:1.6;word-break:break-all\"></div>\n    </div>\n  </div>\n</div>\n<div id=\"recent-panel\">\n  <div class=\"panel-header\"><span>\u6700\u8fd1\u524a\u9664\u3057\u305f\u30bf\u30d6</span></div>\n  <div class=\"panel-list\" id=\"rp-list\"></div>\n</div>\n\n<!-- Modals -->\n<div class=\"modal-bg\" id=\"rename-modal\">\n  <div class=\"modal-box\"><h3>\u30bf\u30d6\u540d\u3092\u5909\u66f4</h3>\n    <div class=\"field\"><input type=\"text\" id=\"rename-input\" placeholder=\"\u30bf\u30d6\u540d\"></div>\n    <div class=\"btn-row\"><button class=\"btn-accent\" onclick=\"confirmRename()\">\u4fdd\u5b58</button><button class=\"btn-outline\" onclick=\"closeModal('rename-modal')\">\u30ad\u30e3\u30f3\u30bb\u30eb</button></div>\n  </div>\n</div>\n\n<!-- Playlist share -->\n<div class=\"modal-bg\" id=\"share-modal\">\n  <div class=\"modal-box\"><h3>\u30d7\u30ec\u30a4\u30ea\u30b9\u30c8\u3092\u5171\u6709</h3>\n    <div class=\"sec\">\u5171\u6709\u3059\u308b\u30bf\u30d6\u3092\u9078\u629e</div>\n    <div id=\"share-checks\" style=\"margin-bottom:12px\"></div>\n    <div id=\"share-result\" style=\"display:none\">\n      <div class=\"sec\">\u5171\u6709\u30ea\u30f3\u30af</div>\n      <div class=\"share-url\" id=\"share-url-text\"></div>\n      <div class=\"btn-row\" style=\"margin-bottom:8px\">\n        <button class=\"btn-accent btn-sm\" onclick=\"copyShareUrl()\">URL\u3092\u30b3\u30d4\u30fc</button>\n        <button class=\"btn-outline btn-sm\" onclick=\"copyShareJson()\">JSON\u3092\u30b3\u30d4\u30fc</button>\n      </div>\n    </div>\n    <div class=\"btn-row\"><button class=\"btn-accent\" onclick=\"generateShareUrl()\">URL\u3092\u751f\u6210</button><button class=\"btn-outline\" onclick=\"closeModal('share-modal')\">\u9589\u3058\u308b</button></div>\n  </div>\n</div>\n\n<!-- Schedule share -->\n<div class=\"modal-bg\" id=\"sched-share-modal\">\n  <div class=\"modal-box\"><h3>\u4e88\u5b9a\u3092\u5171\u6709</h3>\n    <div class=\"sec\">\u5171\u6709\u3059\u308b\u4e88\u5b9a\u3092\u9078\u629e</div>\n    <div style=\"margin-bottom:8px;display:flex;gap:6px\">\n      <button class=\"btn-outline btn-sm\" onclick=\"schedShareSelectAll()\">\u5168\u9078\u629e</button>\n      <button class=\"btn-outline btn-sm\" onclick=\"schedShareSelectNone()\">\u5168\u89e3\u9664</button>\n    </div>\n    <div id=\"sched-share-checks\" style=\"margin-bottom:12px;max-height:200px;overflow-y:auto\"></div>\n    <div id=\"sched-share-result\" style=\"display:none\">\n      <div class=\"sec\">\u5171\u6709\u30ea\u30f3\u30af</div>\n      <div class=\"share-url\" id=\"sched-share-url\"></div>\n      <div class=\"btn-row\" style=\"margin-bottom:8px\">\n        <button class=\"btn-accent btn-sm\" onclick=\"copySchedShareUrl()\">URL\u3092\u30b3\u30d4\u30fc</button>\n        <button class=\"btn-outline btn-sm\" onclick=\"copySchedShareJson()\">JSON\u3092\u30b3\u30d4\u30fc</button>\n      </div>\n    </div>\n    <div class=\"btn-row\"><button class=\"btn-accent\" onclick=\"generateSchedShareUrl()\">URL\u3092\u751f\u6210</button><button class=\"btn-outline\" onclick=\"closeModal('sched-share-modal')\">\u9589\u3058\u308b</button></div>\n  </div>\n</div>\n\n<!-- Import modal -->\n<div class=\"modal-bg\" id=\"import-modal\">\n  <div class=\"modal-box\"><h3 id=\"import-title\">\u30a4\u30f3\u30dd\u30fc\u30c8</h3>\n    <div class=\"sec\">\u30a4\u30f3\u30dd\u30fc\u30c8\u3059\u308b\u3082\u306e\u3092\u9078\u629e</div>\n    <div id=\"import-checks\" style=\"margin-bottom:12px;max-height:260px;overflow-y:auto\"></div>\n    <div class=\"btn-row\">\n      <button class=\"btn-accent\" onclick=\"confirmImport()\">\u30a4\u30f3\u30dd\u30fc\u30c8</button>\n      <button class=\"btn-outline\" onclick=\"closeModal('import-modal')\">\u30ad\u30e3\u30f3\u30bb\u30eb</button>\n    </div>\n  </div>\n</div>\n\n<div class=\"modal-bg\" id=\"delete-modal\">\n  <div class=\"modal-box\"><h3>\u4e88\u5b9a\u3092\u524a\u9664</h3>\n    <p style=\"font-size:12px;margin-bottom:14px\" id=\"delete-msg\"></p>\n    <div class=\"btn-row\"><button class=\"btn-danger\" onclick=\"confirmDelete()\">\u524a\u9664\u3059\u308b</button><button class=\"btn-outline\" onclick=\"closeModal('delete-modal')\">\u30ad\u30e3\u30f3\u30bb\u30eb</button></div>\n  </div>\n</div>\n\n<!-- Add/Edit event -->\n<div class=\"modal-bg\" id=\"event-modal\">\n  <div class=\"modal-box\">\n    <h3 id=\"event-modal-title\">\u4e88\u5b9a\u3092\u8ffd\u52a0</h3>\n    <div class=\"form-grid\">\n      <div class=\"field\"><label>\u6559\u79d1</label><input type=\"text\" id=\"ev-subject\" placeholder=\"\u7406\u79d1\"></div>\n      <div class=\"field\"><label>\u5358\u5143</label><input type=\"text\" id=\"ev-unit\" placeholder=\"\u907a\u4f1d\"></div>\n      <div class=\"field\"><label>\u65e5\u4ed8</label><input type=\"date\" id=\"ev-date\"></div>\n      <div class=\"field\"><label>\u9650</label>\n        <select id=\"ev-period\" onchange=\"onPeriodChange()\">\n          <option value=\"1\">1\u9650 (19:30\u301c)</option>\n          <option value=\"2\">2\u9650 (20:40\u301c)</option>\n          <option value=\"0\">\u30ab\u30b9\u30bf\u30e0</option>\n        </select>\n      </div>\n      <div class=\"field\"><label>\u958b\u59cb\u6642\u523b</label><input type=\"time\" id=\"ev-start\" value=\"19:30\"></div>\n      <div class=\"field\"><label>\u7d42\u4e86\u6642\u523b</label><input type=\"time\" id=\"ev-end\" value=\"21:00\"></div>\n      <div class=\"field\"><label>\u30b9\u30c6\u30fc\u30bf\u30b9</label>\n        <select id=\"ev-status\">\n          <option value=\"normal\">\u3007 \u901a\u5e38\u6388\u696d</option>\n          <option value=\"h_class\">H H\u30af\u30e9\u30b9</option>\n          <option value=\"s_class\">S S\u30af\u30e9\u30b9</option>\n        </select>\n      </div>\n      <div class=\"field\"><label>\u901a\u77e5 (\u5206\u524d)</label><input type=\"text\" id=\"ev-notify\" value=\"60,30,10\"></div>\n    </div>\n    <div class=\"field\"><label>Zoom/\u53c2\u52a0URL</label><input type=\"url\" id=\"ev-link\" placeholder=\"https://zoom.us/j/...\"></div>\n    <div class=\"field\"><label>\u30e1\u30e2</label><input type=\"text\" id=\"ev-memo\" placeholder=\"\u63d0\u51fa\u7269\u306a\u3069\"></div>\n    <div id=\"ev-err\" class=\"errmsg\"></div>\n    <div class=\"btn-row\">\n      <button class=\"btn-accent\" onclick=\"submitEvent()\">\u4fdd\u5b58</button>\n      <button class=\"btn-outline\" onclick=\"closeModal('event-modal')\">\u30ad\u30e3\u30f3\u30bb\u30eb</button>\n    </div>\n  </div>\n</div>\n\n<script>\n// \u2500\u2500 Config (injected by Worker) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nconst WORKER = window.__CFG?.worker || location.origin;\nconst VAPID  = window.__CFG?.vapid  || '';\nconst ONLINE = 'online';\nconst isMobile = () => window.matchMedia('(pointer:coarse)').matches;\n\n// \u2500\u2500 Color palette (subject-based auto color) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nconst PALETTE = [\n  '#7fffb2','#7fb8ff','#ff7f50','#ffcc33',\n  '#c77fff','#ff7fb0','#7fffd4','#ffa07a',\n  '#87ceeb','#98fb98','#dda0dd','#f0e68c',\n];\nfunction subjectColor(subject) {\n  if (!subject) return PALETTE[0];\n  let h = 0;\n  for (let i = 0; i < subject.length; i++) { h = (h << 5) - h + subject.charCodeAt(i); h |= 0; }\n  return PALETTE[Math.abs(h) % PALETTE.length];\n}\n\n// \u2500\u2500 State \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nlet tabs      = JSON.parse(localStorage.getItem('yt_tabs')    || '[]');\nlet recents   = JSON.parse(localStorage.getItem('yt_recent')  || '[]');\nlet notifs    = JSON.parse(localStorage.getItem('yt_notifs')  || '[]');\nlet schedules = JSON.parse(localStorage.getItem('yt_schedule')|| '[]');\nlet activeTabId = localStorage.getItem('yt_active_tab') || ONLINE;\nlet swReg = null, pushSub = null, notifOpen = false, recentOpen = false, renameTabId = null;\nlet videoCache = {}, jsonAreaOpen = false, viewMode = 'list';\nlet calYear = new Date().getFullYear(), calMonth = new Date().getMonth(), calSelected = null, calFilter = 'all';\nlet selectedSet = new Set(), sortedIndices = [], lastClickedSorted = -1, selectionMode = false, longPressTimer = null;\nlet editingEventIdx = -1;\nlet pendingImport = null;\n\nif (!tabs.length) { tabs = [newTab('\u30d7\u30ec\u30a4\u30ea\u30b9\u30c8 1', '')]; saveTabs(); }\nif (!tabs.find(t => t.id === activeTabId) && activeTabId !== ONLINE) activeTabId = ONLINE;\n\nfunction newTab(n, p) { return { id: Date.now().toString(36) + Math.random().toString(36).slice(2,6), name: n, playlistId: p, createdAt: Date.now() }; }\nfunction saveTabs()    { localStorage.setItem('yt_tabs', JSON.stringify(tabs)); localStorage.setItem('yt_active_tab', activeTabId); }\nfunction saveRecents() { localStorage.setItem('yt_recent', JSON.stringify(recents)); }\nfunction saveSchedule(){ localStorage.setItem('yt_schedule', JSON.stringify(schedules)); syncScheduleToKV(); }\nasync function syncScheduleToKV() {\n  try { await fetch(`${WORKER}/schedules`, { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({schedules}) }); } catch {}\n}\n\n// \u2500\u2500 Init \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n(async () => {\n  // Import from URL\n  const p = new URLSearchParams(location.search);\n  const imp = p.get('import');\n  if (imp) {\n    try {\n      const b64 = imp.replace(/-/g,'+').replace(/_/g,'/');\n      const json = JSON.parse(decodeURIComponent(atob(b64)));\n      showImportModal(json);\n    } catch(e) { console.warn('import err:', e); }\n    history.replaceState({}, '', location.pathname);\n  }\n  if ('serviceWorker' in navigator) {\n    try { swReg = await navigator.serviceWorker.register('/sw.js'); await navigator.serviceWorker.ready; pushSub = await swReg.pushManager.getSubscription(); updatePushBadge(); } catch {}\n  }\n  renderTabBar(); renderApp(); updateNotifBadge();\n  if (schedules.length) renderScheduleCards();\n  setupKeyboard(); updatePushDebug();\n  document.getElementById('ev-period').addEventListener('change', onPeriodChange);\n})();\n\n// \u2500\u2500 Period auto-fill \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nfunction onPeriodChange() {\n  const v = document.getElementById('ev-period').value;\n  if (v==='1') { document.getElementById('ev-start').value='19:30'; document.getElementById('ev-end').value='21:00'; }\n  else if (v==='2') { document.getElementById('ev-start').value='20:40'; document.getElementById('ev-end').value='23:00'; }\n}\n\n// \u2500\u2500 Keyboard \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nfunction setupKeyboard() {\n  document.addEventListener('keydown', e => {\n    if (activeTabId !== ONLINE) return;\n    const tag = document.activeElement.tagName;\n    if (tag==='INPUT'||tag==='TEXTAREA'||tag==='SELECT') return;\n    if ((e.ctrlKey||e.metaKey) && e.key==='a') { e.preventDefault(); selectAll(); }\n    if ((e.key==='x'||e.key==='X') && !e.ctrlKey && selectedSet.size>0) showDeleteConfirm();\n    if (e.key==='Escape') clearSelection();\n  });\n}\n\n// \u2500\u2500 View toggle \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nfunction toggleView() {\n  viewMode = viewMode==='list' ? 'cal' : 'list';\n  document.getElementById('view-btn').textContent = viewMode==='list' ? '\u30ab\u30ec\u30f3\u30c0\u30fc' : '\u30ea\u30b9\u30c8';\n  document.getElementById('cal-wrap').classList.toggle('show', viewMode==='cal');\n  document.getElementById('list-wrap').style.display = viewMode==='list' ? '' : 'none';\n  if (viewMode==='cal') renderCalendar();\n}\n\n// \u2500\u2500 Calendar filter \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nfunction setCalFilter(f) {\n  calFilter = f;\n  ['all','notify','future'].forEach(id => document.getElementById('filt-'+id).classList.toggle('active', id===f));\n  calSelected = null;\n  document.getElementById('cal-events').style.display = 'none';\n  renderCalendar();\n}\n\nfunction filteredSchedules() {\n  const now = new Date();\n  return schedules.filter(s => {\n    if (calFilter==='notify' && !s.notify) return false;\n    if (calFilter==='future') {\n      const d = new Date(s.date+'T'+(s.startTime||'00:00'));\n      if (d < now) return false;\n    }\n    return true;\n  });\n}\n\n// \u2500\u2500 Calendar \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nfunction calMove(d) { calMonth+=d; if(calMonth>11){calMonth=0;calYear++;} if(calMonth<0){calMonth=11;calYear--;} calSelected=null; document.getElementById('cal-events').style.display='none'; renderCalendar(); }\nfunction toDateStr(d) { return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0'); }\n\nfunction renderCalendar() {\n  document.getElementById('cal-title').textContent = calYear+'\u5e74'+(calMonth+1)+'\u6708';\n  const grid = document.getElementById('cal-grid');\n  const days = ['\u65e5','\u6708','\u706b','\u6c34','\u6728','\u91d1','\u571f'];\n  let html = days.map(d=>`<div class=\"cal-head\">${d}</div>`).join('');\n\n  const first = new Date(calYear, calMonth, 1);\n  const startDow = first.getDay();\n  const daysInMonth = new Date(calYear, calMonth+1, 0).getDate();\n  const prevDays = new Date(calYear, calMonth, 0).getDate();\n  const todayStr = toDateStr(new Date());\n\n  const evMap = {};\n  filteredSchedules().forEach(s => { if(s.date) evMap[s.date] = (evMap[s.date]||[]).concat(s); });\n\n  for (let i=startDow-1; i>=0; i--) {\n    const d=prevDays-i, ds=toDateStr(new Date(calYear,calMonth-1,d));\n    html += dayCell(d, ds, evMap[ds]||[], 'other-month');\n  }\n  for (let d=1; d<=daysInMonth; d++) {\n    const ds = toDateStr(new Date(calYear,calMonth,d));\n    const cls = (ds===todayStr?'today':'') + (ds===calSelected?' selected':'');\n    html += dayCell(d, ds, evMap[ds]||[], cls);\n  }\n  const total = startDow+daysInMonth;\n  const remain = (7-total%7)%7;\n  for (let d=1; d<=remain; d++) {\n    const ds = toDateStr(new Date(calYear,calMonth+1,d));\n    html += dayCell(d, ds, evMap[ds]||[], 'other-month');\n  }\n  grid.innerHTML = html;\n  if (calSelected) {\n    const ev = document.getElementById('cal-events');\n    renderCalEvents(calSelected, evMap[calSelected]||[]);\n    ev.style.display = '';\n  }\n}\n\nfunction dayCell(d, ds, events, extra) {\n  // Unique subjects \u2192 unique color dots\n  const seen = new Set();\n  const dots = events.map(e => {\n    const c = subjectColor(e.subject);\n    if (seen.has(c)) return '';\n    seen.add(c);\n    return `<span class=\"cal-dot\" style=\"background:${c}\"></span>`;\n  }).join('');\n  return `<div class=\"cal-day ${extra}\" onclick=\"calSelect('${ds}')\"><div class=\"cal-dn\">${d}</div><div class=\"cal-dots\">${dots}</div></div>`;\n}\n\nfunction calSelect(ds) {\n  calSelected = ds;\n  const evMap = {};\n  filteredSchedules().forEach(s => { if(s.date) evMap[s.date] = (evMap[s.date]||[]).concat(s); });\n  renderCalendar();\n  const ev = document.getElementById('cal-events');\n  renderCalEvents(ds, evMap[ds]||[]);\n  ev.style.display = '';\n}\n\nfunction renderCalEvents(ds, events) {\n  const el = document.getElementById('cal-events');\n  if (!events.length) { el.innerHTML='<div class=\"empty\" style=\"padding:14px\">\u3053\u306e\u65e5\u306e\u4e88\u5b9a\u306f\u3042\u308a\u307e\u305b\u3093</div>'; return; }\n  const rel = getRelative(ds);\n  el.innerHTML = `<div class=\"cal-events-box\"><h4>${ds} <span class=\"s-rel ${rel.cls}\" style=\"font-size:10px\">${rel.text}</span><span style=\"font-size:10px;color:var(--muted);margin-left:4px\">${events.length}\u4ef6</span></h4>\n  ${events.map(e => {\n    const origIdx = schedules.findIndex(x => x.eventId===e.eventId);\n    const color = subjectColor(e.subject);\n    const link = e.link?.url || e.zoomUrl || '';\n    return `<div class=\"cal-ev\" style=\"border-left-color:${color};background:${color}11\">\n      <div class=\"cal-ev-sub\">\n        <span style=\"color:${color}\">${esc(e.subject||'')} <span style=\"font-weight:normal;color:var(--muted);font-size:10px\">${esc(e.unit||'')}</span></span>\n        <span class=\"s-status ${e.status||'normal'}\" style=\"font-size:10px\">${esc(e.statusName||'\u901a\u5e38')}</span>\n      </div>\n      <div class=\"cal-ev-meta\">${esc(e.timeSlot||'')} ${esc(e.startTime||'')}\u301c${esc(e.endTime||'')}${e.isDefaultTime?'<span style=\"opacity:.6\"> (\u30c7\u30d5\u30a9\u30eb\u30c8)</span>':''}</div>\n      ${e.memo?`<div style=\"font-size:10px;color:var(--muted);margin-top:2px\">${esc(e.memo)}</div>`:''}\n      <div class=\"cal-ev-actions\">\n        <label class=\"tog-wrap\" onclick=\"event.stopPropagation()\">\n          <svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"var(--muted)\"><path d=\"M12 22c1.1 0 2-.9 2-2h-4c0 1.1.9 2 2 2zm6-6v-5c0-3.07-1.64-5.64-4.5-6.32V4c0-.83-.67-1.5-1.5-1.5s-1.5.67-1.5 1.5v.68C7.63 5.36 6 7.92 6 11v5l-2 2v1h16v-1l-2-2z\"/></svg>\n          <label class=\"tog\"><input type=\"checkbox\" ${e.notify?'checked':''} onchange=\"schedSet(${origIdx},'notify',this.checked);calSelect('${ds}')\"><span class=\"tog-sl\"></span></label>\n        </label>\n        <label class=\"tog-wrap\" onclick=\"event.stopPropagation()\">\n          \u5b8c\u4e86\n          <label class=\"tog done\"><input type=\"checkbox\" ${e.completed?'checked':''} onchange=\"schedSet(${origIdx},'completed',this.checked);calSelect('${ds}')\"><span class=\"tog-sl\"></span></label>\n        </label>\n        ${link?`<button class=\"s-link-btn\" onclick=\"window.open('${link}','_blank')\"><svg viewBox=\"0 0 24 24\"><path d=\"M19 19H5V5h7V3H5c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2v-7h-2v7zM14 3v2h3.59l-9.83 9.83 1.41 1.41L19 6.41V10h2V3h-7z\"/></svg>\u53c2\u52a0/\u958b\u304f</button>`:''}\n        <button class=\"sel-btn btn-sm\" style=\"font-size:10px\" onclick=\"openAddEvent(${origIdx});closeModal('import-modal')\">\u7de8\u96c6</button>\n      </div>\n    </div>`;\n  }).join('')}</div>`;\n}\n\n// \u2500\u2500 Selection \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nfunction toggleSelect(sp) { const i=sortedIndices[sp]; if(selectedSet.has(i))selectedSet.delete(i); else selectedSet.add(i); lastClickedSorted=sp; updateSelUI(); }\nfunction shiftSelect(sp) { if(lastClickedSorted===-1){toggleSelect(sp);return;} const f=Math.min(lastClickedSorted,sp),t=Math.max(lastClickedSorted,sp); for(let i=f;i<=t;i++)selectedSet.add(sortedIndices[i]); lastClickedSorted=sp; updateSelUI(); }\nfunction selectAll() { sortedIndices.forEach(i=>selectedSet.add(i)); lastClickedSorted=sortedIndices.length-1; updateSelUI(); }\nfunction clearSelection() { selectedSet.clear(); lastClickedSorted=-1; if(isMobile())exitSelectionMode(); else updateSelUI(); }\nfunction exitSelectionMode() { selectionMode=false; selectedSet.clear(); lastClickedSorted=-1; updateSelUI(); }\nfunction updateSelUI() {\n  const n = selectedSet.size;\n  if (!isMobile()) {\n    document.getElementById('sel-toolbar').classList.toggle('show', n>0);\n    document.getElementById('sel-count-text').textContent = n+'\u4ef6\u9078\u629e\u4e2d';\n    document.getElementById('mobile-sel-banner').classList.remove('show');\n  } else {\n    document.getElementById('sel-toolbar').classList.remove('show');\n    document.getElementById('mobile-sel-banner').classList.toggle('show', selectionMode);\n    document.getElementById('mb-sel-txt').textContent = selectionMode ? n+'\u4ef6\u9078\u629e\u4e2d' : '\u9078\u629e\u30e2\u30fc\u30c9';\n    document.getElementById('mb-del-btn').style.display = (selectionMode&&n>0)?'flex':'none';\n  }\n  document.querySelectorAll('.s-card[data-sp]').forEach(card => {\n    card.classList.toggle('selected', selectedSet.has(sortedIndices[parseInt(card.dataset.sp)]));\n  });\n}\nfunction onCardTouchStart(e,sp){longPressTimer=setTimeout(()=>{longPressTimer=null;selectionMode=true;selectedSet.clear();selectedSet.add(sortedIndices[sp]);lastClickedSorted=sp;navigator.vibrate?.(30);updateSelUI();},500);}\nfunction onCardTouchEnd(){clearTimeout(longPressTimer);longPressTimer=null;}\nfunction onCardTouchMove(){clearTimeout(longPressTimer);longPressTimer=null;}\nfunction onCardClick(e,sp){if(!isMobile())return;if(!selectionMode)return;e.preventDefault();toggleSelect(sp);}\nfunction onCheckboxClick(e,sp){e.stopPropagation();if(e.shiftKey)shiftSelect(sp);else toggleSelect(sp);}\nfunction showDeleteConfirm(){if(!selectedSet.size)return;document.getElementById('delete-msg').textContent=selectedSet.size+'\u4ef6\u306e\u4e88\u5b9a\u3092\u524a\u9664\u3057\u307e\u3059\u304b\uff1f';document.getElementById('delete-modal').classList.add('open');}\nfunction confirmDelete(){[...selectedSet].sort((a,b)=>b-a).forEach(i=>schedules.splice(i,1));saveSchedule();clearSelection();closeModal('delete-modal');renderScheduleCards();if(viewMode==='cal')renderCalendar();}\n\n// \u2500\u2500 Add/Edit event \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nfunction openAddEvent(idx=-1) {\n  editingEventIdx=idx;\n  const isEdit=idx>=0;\n  document.getElementById('event-modal-title').textContent=isEdit?'\u4e88\u5b9a\u3092\u7de8\u96c6':'\u4e88\u5b9a\u3092\u8ffd\u52a0';\n  document.getElementById('ev-err').style.display='none';\n  if (isEdit) {\n    const s=schedules[idx];\n    ['ev-subject','ev-unit','ev-date','ev-start','ev-end','ev-link','ev-memo'].forEach(id=>{\n      const map={['ev-subject']:s.subject,'ev-unit':s.unit,'ev-date':s.date,'ev-start':s.startTime,'ev-end':s.endTime,'ev-link':s.link?.url||s.zoomUrl||'','ev-memo':s.memo||''};\n      const el=document.getElementById(id); if(el)el.value=map[id]||'';\n    });\n    document.getElementById('ev-period').value=s.period||1;\n    document.getElementById('ev-status').value=s.status||'normal';\n    document.getElementById('ev-notify').value=(s.notifyBefore||[60,30,10]).join(',');\n  } else {\n    document.getElementById('ev-subject').value=''; document.getElementById('ev-unit').value='';\n    document.getElementById('ev-date').value=new Date().toISOString().slice(0,10);\n    document.getElementById('ev-period').value='1';\n    document.getElementById('ev-start').value='19:30'; document.getElementById('ev-end').value='21:00';\n    document.getElementById('ev-status').value='normal'; document.getElementById('ev-notify').value='60,30,10';\n    document.getElementById('ev-link').value=''; document.getElementById('ev-memo').value='';\n  }\n  document.getElementById('event-modal').classList.add('open');\n}\n\nfunction submitEvent() {\n  const subject = document.getElementById('ev-subject').value.trim();\n  const date    = document.getElementById('ev-date').value;\n  const errEl   = document.getElementById('ev-err');\n  if (!subject) { errEl.textContent='\u6559\u79d1\u3092\u5165\u529b\u3057\u3066\u304f\u3060\u3055\u3044'; errEl.style.display='block'; return; }\n  if (!date)    { errEl.textContent='\u65e5\u4ed8\u3092\u5165\u529b\u3057\u3066\u304f\u3060\u3055\u3044';   errEl.style.display='block'; return; }\n\n  const period    = parseInt(document.getElementById('ev-period').value)||0;\n  const startTime = document.getElementById('ev-start').value;\n  const endTime   = document.getElementById('ev-end').value;\n  const statusVal = document.getElementById('ev-status').value;\n  const statusNames = {normal:'\u901a\u5e38\u6388\u696d',h_class:'H\u30af\u30e9\u30b9',s_class:'S\u30af\u30e9\u30b9'};\n  const notifyBefore = document.getElementById('ev-notify').value.split(',').map(v=>parseInt(v.trim())).filter(n=>!isNaN(n));\n  const linkUrl   = document.getElementById('ev-link').value.trim();\n  const weekday   = ['\u65e5','\u6708','\u706b','\u6c34','\u6728','\u91d1','\u571f'][new Date(date).getDay()];\n\n  const entry = {\n    eventId: editingEventIdx>=0 ? schedules[editingEventIdx].eventId : 'evt_'+Math.random().toString(36).slice(2,10),\n    subject, unit: document.getElementById('ev-unit').value.trim(), date,\n    displayDate: date.slice(5).replace('-','/'), weekday, period,\n    timeSlot: period>0?period+'\u9650':'',\n    startTime, endTime, isDefaultTime:false,\n    status: statusVal, statusName: statusNames[statusVal]||'\u901a\u5e38\u6388\u696d',\n    zoomUrl: linkUrl,\n    link: linkUrl ? {url:linkUrl,type:linkUrl.includes('zoom')?'zoom':'external',target:'_blank'} : {url:''},\n    notify: editingEventIdx>=0 ? schedules[editingEventIdx].notify : false,\n    notifyBefore, memo: document.getElementById('ev-memo').value.trim(),\n    completed: editingEventIdx>=0 ? schedules[editingEventIdx].completed : false,\n    confidence: 1.0,\n  };\n\n  if (editingEventIdx>=0) schedules[editingEventIdx]=entry;\n  else schedules.push(entry);\n\n  saveSchedule();\n  closeModal('event-modal');\n  renderScheduleCards();\n  if (viewMode==='cal') renderCalendar();\n}\n\n// \u2500\u2500 Schedule JSON \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nfunction toggleJsonArea(){jsonAreaOpen=!jsonAreaOpen;document.getElementById('sched-json').classList.toggle('open',jsonAreaOpen);document.getElementById('sched-load-row').style.display=jsonAreaOpen?'flex':'none';if(jsonAreaOpen)document.getElementById('sched-json').focus();}\n\nfunction loadScheduleJson(){\n  const raw=document.getElementById('sched-json').value.trim();\n  const errEl=document.getElementById('sched-err');errEl.style.display='none';\n  try{\n    let input=JSON.parse(raw);let arr=Array.isArray(input)?input:(input.schedule||[]);\n    if(!arr.length)throw new Error('schedule\u304c\u7a7a\u3067\u3059');\n    let added=0,skipped=0;\n    arr.forEach(s=>{\n      s=fillDefaultTime(s);\n      const dup=schedules.find(x=>x.eventId===s.eventId||(x.subject===s.subject&&x.unit===s.unit&&x.date===s.date&&x.period===s.period&&x.status===s.status));\n      if(dup){skipped++;return;}schedules.push(s);added++;\n    });\n    saveSchedule();toggleJsonArea();document.getElementById('sched-json').value='';\n    renderScheduleCards();if(viewMode==='cal')renderCalendar();\n    if(skipped){errEl.textContent=`${added}\u4ef6\u8ffd\u52a0\u3001${skipped}\u4ef6\u91cd\u8907\u30b9\u30ad\u30c3\u30d7`;errEl.style.display='block';}\n  }catch(e){errEl.textContent='JSON\u30a8\u30e9\u30fc: '+e.message;errEl.style.display='block';}\n}\n\nfunction clearSchedule(){if(!confirm('\u5168\u4e88\u5b9a\u3092\u524a\u9664\u3057\u307e\u3059\u304b\uff1f'))return;schedules=[];saveSchedule();selectedSet.clear();renderScheduleCards();if(viewMode==='cal')renderCalendar();}\n\nfunction fillDefaultTime(s){\n  if(!s.startTime){\n    if(s.period===1){s.startTime='19:30';s.endTime=s.endTime||'21:00';s.isDefaultTime=true;}\n    else if(s.period===2){s.startTime='20:40';s.endTime=s.endTime||'23:00';s.isDefaultTime=true;}\n    else{s.startTime='00:00';s.isDefaultTime=true;}\n  }else{s.isDefaultTime=false;if(!s.endTime)s.endTime=calcEnd(s.startTime);}\n  return s;\n}\nfunction calcEnd(start){let[h,m]=start.split(':').map(Number);m+=90;h+=Math.floor(m/60);m%=60;return String(h).padStart(2,'0')+':'+String(m).padStart(2,'0');}\nfunction getRelative(ds){\n  const today=new Date();today.setHours(0,0,0,0);\n  const target=new Date(ds);target.setHours(0,0,0,0);\n  const diff=Math.floor((target-today)/86400000);\n  if(diff===0)return{text:'\u4eca\u65e5',cls:'today'};if(diff===1)return{text:'\u660e\u65e5',cls:'future'};\n  if(diff===2)return{text:'\u660e\u5f8c\u65e5',cls:'future'};if(diff===-1)return{text:'\u6628\u65e5',cls:'past'};\n  if(diff===-2)return{text:'\u4e00\u6628\u65e5',cls:'past'};if(diff>2)return{text:`${diff}\u65e5\u5f8c`,cls:'future'};\n  return{text:`${Math.abs(diff)}\u65e5\u524d`,cls:'past'};\n}\n\n// \u2500\u2500 Render cards \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nfunction renderScheduleCards(){\n  const container=document.getElementById('sched-cards');\n  if(!schedules.length){container.innerHTML='<div class=\"empty\">\u300c\uff0b \u8ffd\u52a0\u300d\u307e\u305f\u306fJSON\u3092\u8aad\u307f\u8fbc\u3093\u3067\u304f\u3060\u3055\u3044</div>';sortedIndices=[];updateSelUI();return;}\n  const now=new Date();\n  const withIdx=schedules.map((s,i)=>({s,i}));\n  withIdx.sort((a,b)=>{\n    const ta=new Date(a.s.date+'T'+(a.s.startTime||'00:00'));\n    const tb=new Date(b.s.date+'T'+(b.s.startTime||'00:00'));\n    const ap=ta<now,bp=tb<now;\n    if(ap!==bp)return ap?1:-1;if(!ap&&!bp)return ta-tb;return tb-ta;\n  });\n  sortedIndices=withIdx.map(x=>x.i);\n  let html='',pastStarted=false;\n  withIdx.forEach(({s,i},sp)=>{\n    const rel=getRelative(s.date);\n    const ta=new Date(s.date+'T'+(s.startTime||'00:00'));\n    if(!pastStarted&&ta<now){pastStarted=true;html+='<div class=\"s-divider\">\u2500\u2500\u2500 \u904e\u53bb\u306e\u4e88\u5b9a \u2500\u2500\u2500</div>';}\n    const sel=selectedSet.has(i)?'selected':'';\n    const link=s.link?.url||s.zoomUrl||'';\n    const color=subjectColor(s.subject);\n    html+=`<div class=\"s-card ${s.notify?'notify-on':''} ${s.completed?'completed':''} ${sel}\" data-sp=\"${sp}\"\n      style=\"${s.notify?`border-left-color:${color}`:''}border-top:1px solid ${color}22\"\n      onclick=\"onCardClick(event,${sp})\"\n      ontouchstart=\"onCardTouchStart(event,${sp})\"\n      ontouchend=\"onCardTouchEnd()\"\n      ontouchmove=\"onCardTouchMove()\">\n      <div class=\"s-cb-col\" onclick=\"onCheckboxClick(event,${sp})\">\n        <div class=\"s-checkbox\"><svg viewBox=\"0 0 12 12\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"1,6 4,10 11,2\"/></svg></div>\n      </div>\n      <div class=\"s-body\">\n        <div class=\"s-head\">\n          <div>\n            <div class=\"s-subject\" style=\"color:${color}\">${esc(s.subject||'')}</div>\n            <div class=\"s-unit\">${esc(s.unit||'')}</div>\n          </div>\n          <div style=\"display:flex;gap:5px;align-items:center\">\n            <label class=\"tog-wrap\" onclick=\"event.stopPropagation()\">\n              <svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"var(--muted)\"><path d=\"M12 22c1.1 0 2-.9 2-2h-4c0 1.1.9 2 2 2zm6-6v-5c0-3.07-1.64-5.64-4.5-6.32V4c0-.83-.67-1.5-1.5-1.5s-1.5.67-1.5 1.5v.68C7.63 5.36 6 7.92 6 11v5l-2 2v1h16v-1l-2-2z\"/></svg>\n              <label class=\"tog\"><input type=\"checkbox\" ${s.notify?'checked':''} onchange=\"schedSet(${i},'notify',this.checked)\"><span class=\"tog-sl\" style=\"${s.notify?`background:${color}`:''}\"></span></label>\n            </label>\n            <button class=\"sel-btn\" style=\"font-size:10px;padding:2px 6px\" onclick=\"event.stopPropagation();openAddEvent(${i})\">\u7de8\u96c6</button>\n          </div>\n        </div>\n        <div class=\"s-date\">\n          <svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"var(--muted)\"><path d=\"M19 4h-1V2h-2v2H8V2H6v2H5c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2V6c0-1.1-.9-2-2-2zm0 16H5V9h14v11z\"/></svg>\n          ${esc(s.date||'')} ${esc(s.weekday||'')} ${esc(s.timeSlot||'')}\n        </div>\n        <div class=\"s-time\">\n          <svg width=\"11\" height=\"11\" viewBox=\"0 0 24 24\" fill=\"var(--muted)\"><path d=\"M12 2C6.5 2 2 6.5 2 12s4.5 10 10 10 10-4.5 10-10S17.5 2 12 2zm.5 5v5.25l4.5 2.67-.75 1.23L11 13V7h1.5z\"/></svg>\n          ${esc(s.startTime||'')} ~ ${esc(s.endTime||'')}${s.isDefaultTime?'<span class=\"s-def\">(\u30c7\u30d5\u30a9\u30eb\u30c8)</span>':''}\n        </div>\n        <div class=\"s-badges\">\n          <span class=\"s-rel ${rel.cls}\">${rel.text}</span>\n          <span class=\"s-status ${s.status||'normal'}\">${esc(s.statusName||'\u901a\u5e38\u6388\u696d')}</span>\n          ${link?`<button class=\"s-link-btn\" onclick=\"event.stopPropagation();window.open('${link}','_blank')\"><svg viewBox=\"0 0 24 24\"><path d=\"M19 19H5V5h7V3H5c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2v-7h-2v7zM14 3v2h3.59l-9.83 9.83 1.41 1.41L19 6.41V10h2V3h-7z\"/></svg>\u53c2\u52a0/\u958b\u304f</button>`:''}\n        </div>\n        ${s.notifyBefore?.length?`<div style=\"font-size:10px;color:var(--muted)\">\u901a\u77e5: ${s.notifyBefore.join(', ')}\u5206\u524d</div>`:''}\n        <div onclick=\"event.stopPropagation()\">\n          <input type=\"text\" value=\"${esc(s.memo||'')}\" placeholder=\"\u30e1\u30e2\" onchange=\"schedSet(${i},'memo',this.value)\">\n        </div>\n        <div onclick=\"event.stopPropagation()\">\n          <label class=\"tog-wrap\">\u5b8c\u4e86<label class=\"tog done\"><input type=\"checkbox\" ${s.completed?'checked':''} onchange=\"schedSet(${i},'completed',this.checked)\"><span class=\"tog-sl\"></span></label></label>\n        </div>\n      </div>\n    </div>`;\n  });\n  container.innerHTML=html; updateSelUI();\n}\n\nfunction schedSet(idx,key,val){if(idx<0||idx>=schedules.length)return;schedules[idx][key]=val;saveSchedule();if(key==='notify'||key==='completed'){renderScheduleCards();if(viewMode==='cal')renderCalendar();}}\n\n// \u2500\u2500 Schedule share \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nfunction openSchedShare(){\n  const checks=document.getElementById('sched-share-checks');\n  checks.innerHTML=schedules.map((s,i)=>{\n    const color=subjectColor(s.subject);\n    return `<label style=\"display:flex;align-items:center;gap:8px;margin-bottom:6px;font-size:12px;cursor:pointer\">\n      <input type=\"checkbox\" value=\"${i}\" checked style=\"accent-color:${color}\">\n      <span style=\"color:${color}\">${esc(s.subject||'')}</span>\n      <span style=\"font-size:10px;color:var(--muted)\">${esc(s.unit||'')} ${esc(s.date||'')}</span>\n    </label>`;\n  }).join('');\n  document.getElementById('sched-share-result').style.display='none';\n  document.getElementById('sched-share-modal').classList.add('open');\n}\nfunction schedShareSelectAll(){document.querySelectorAll('#sched-share-checks input').forEach(el=>el.checked=true);}\nfunction schedShareSelectNone(){document.querySelectorAll('#sched-share-checks input').forEach(el=>el.checked=false);}\nfunction getSelectedSchedules(){\n  const checked=[...document.querySelectorAll('#sched-share-checks input:checked')].map(el=>parseInt(el.value));\n  return checked.map(i=>schedules[i]).filter(Boolean);\n}\nfunction generateSchedShareUrl(){\n  const sel=getSelectedSchedules();if(!sel.length)return;\n  const payload={type:'schedule',data:sel};\n  const b64=btoa(encodeURIComponent(JSON.stringify(payload)));\n  const safe=b64.replace(/\\+/g,'-').replace(/\\//g,'_').replace(/=/g,'');\n  const url=`${location.origin}?import=${safe}`;\n  document.getElementById('sched-share-url').textContent=url;\n  document.getElementById('sched-share-result').style.display='block';\n}\nfunction copySchedShareUrl(){navigator.clipboard.writeText(document.getElementById('sched-share-url').textContent).then(()=>alert('URL\u3092\u30b3\u30d4\u30fc\u3057\u307e\u3057\u305f'));}\nfunction copySchedShareJson(){navigator.clipboard.writeText(JSON.stringify(getSelectedSchedules(),null,2)).then(()=>alert('JSON\u3092\u30b3\u30d4\u30fc\u3057\u307e\u3057\u305f'));}\n\n// \u2500\u2500 Playlist share \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nfunction openShare(){\n  document.getElementById('share-checks').innerHTML=tabs.map(t=>`<label style=\"display:flex;align-items:center;gap:8px;margin-bottom:8px;font-size:12px;cursor:pointer\"><input type=\"checkbox\" value=\"${t.id}\" checked style=\"accent-color:var(--accent)\"><span>${esc(t.name)}</span><span style=\"font-size:10px;color:var(--muted)\">${t.playlistId||'\u672a\u8a2d\u5b9a'}</span></label>`).join('');\n  document.getElementById('share-result').style.display='none';\n  document.getElementById('share-modal').classList.add('open');\n}\nfunction getSelectedTabs(){\n  const checked=[...document.querySelectorAll('#share-checks input:checked')].map(el=>el.value);\n  return tabs.filter(t=>checked.includes(t.id)).map(t=>({name:t.name,playlistId:t.playlistId}));\n}\nfunction generateShareUrl(){\n  const selected=getSelectedTabs();if(!selected.length)return;\n  const payload={type:'playlist',data:selected};\n  const b64=btoa(encodeURIComponent(JSON.stringify(payload)));\n  const safe=b64.replace(/\\+/g,'-').replace(/\\//g,'_').replace(/=/g,'');\n  const url=`${location.origin}?import=${safe}`;\n  document.getElementById('share-url-text').textContent=url;\n  document.getElementById('share-result').style.display='block';\n}\nfunction copyShareUrl(){navigator.clipboard.writeText(document.getElementById('share-url-text').textContent).then(()=>alert('URL\u3092\u30b3\u30d4\u30fc\u3057\u307e\u3057\u305f'));}\nfunction copyShareJson(){navigator.clipboard.writeText(JSON.stringify(getSelectedTabs(),null,2)).then(()=>alert('JSON\u3092\u30b3\u30d4\u30fc\u3057\u307e\u3057\u305f'));}\n\n// \u2500\u2500 Import (unified) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nfunction showImportModal(payload) {\n  pendingImport = payload;\n  const isSchedule = payload?.type==='schedule';\n  const isPlaylist  = payload?.type==='playlist' || Array.isArray(payload);\n  const items = isSchedule ? payload.data : (isPlaylist ? (payload.data||payload) : []);\n\n  document.getElementById('import-title').textContent = isSchedule ? '\u4e88\u5b9a\u3092\u30a4\u30f3\u30dd\u30fc\u30c8' : '\u30d7\u30ec\u30a4\u30ea\u30b9\u30c8\u3092\u30a4\u30f3\u30dd\u30fc\u30c8';\n  document.getElementById('import-checks').innerHTML = items.map((item,i)=>{\n    if (isSchedule) {\n      const color = subjectColor(item.subject);\n      return `<label style=\"display:flex;align-items:center;gap:8px;margin-bottom:6px;font-size:12px;cursor:pointer\">\n        <input type=\"checkbox\" value=\"${i}\" checked style=\"accent-color:${color}\">\n        <span style=\"color:${color}\">${esc(item.subject||'')}</span>\n        <span style=\"font-size:10px;color:var(--muted)\">${esc(item.unit||'')} ${esc(item.date||'')}</span>\n      </label>`;\n    } else {\n      return `<label style=\"display:flex;align-items:center;gap:8px;margin-bottom:6px;font-size:12px;cursor:pointer\">\n        <input type=\"checkbox\" value=\"${i}\" checked style=\"accent-color:var(--accent)\">\n        <span>${esc(item.name||'\u7121\u984c')}</span>\n        <span style=\"font-size:10px;color:var(--muted)\">${esc(item.playlistId||'')}</span>\n      </label>`;\n    }\n  }).join('');\n  document.getElementById('import-modal').classList.add('open');\n}\n\nfunction confirmImport(){\n  if (!pendingImport) return closeModal('import-modal');\n  const payload = pendingImport;\n  const isSchedule = payload?.type==='schedule';\n  const items = isSchedule ? payload.data : (payload.data || (Array.isArray(payload)?payload:[]));\n  const checked = [...document.querySelectorAll('#import-checks input:checked')].map(el=>parseInt(el.value));\n\n  if (isSchedule) {\n    let added=0,skipped=0;\n    checked.forEach(i=>{\n      const s=fillDefaultTime({...items[i]});\n      const dup=schedules.find(x=>x.eventId===s.eventId||(x.subject===s.subject&&x.unit===s.unit&&x.date===s.date));\n      if(dup){skipped++;return;}schedules.push(s);added++;\n    });\n    saveSchedule(); renderScheduleCards(); if(viewMode==='cal')renderCalendar();\n    if(skipped) alert(`${added}\u4ef6\u8ffd\u52a0\u3001${skipped}\u4ef6\u306f\u91cd\u8907\u306e\u305f\u3081\u30b9\u30ad\u30c3\u30d7`);\n  } else {\n    checked.forEach(i=>{\n      const d=items[i]; if(!d) return;\n      const tab=newTab(d.name||'\u7121\u984c',d.playlistId||'');\n      tabs.push(tab);\n      const p=document.createElement('div');p.className='pane';p.id='pane-'+tab.id;document.getElementById('app').appendChild(p);\n    });\n    saveTabs(); syncPlaylistsToGitHub(); renderTabBar();\n  }\n  pendingImport=null; closeModal('import-modal');\n}\n\n// \u2500\u2500 Tab system \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nfunction renderTabBar(){\n  const bar=document.getElementById('tabbar'),addBtn=bar.querySelector('.tab-add');\n  bar.querySelectorAll('.tab-item:not(.pinned)').forEach(el=>el.remove());\n  document.getElementById('online-tab').classList.toggle('active',activeTabId===ONLINE);\n  tabs.forEach(tab=>{\n    const el=document.createElement('div');el.className='tab-item'+(tab.id===activeTabId?' active':'');el.dataset.id=tab.id;\n    el.innerHTML=`<svg class=\"tab-icon\" viewBox=\"0 0 24 24\"><path d=\"${tab.playlistId?'M8 5v14l11-7z':'M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 18c-4.42 0-8-3.58-8-8s3.58-8 8-8 8 3.58 8 8-3.58 8-8 8z'}\"/></svg><span class=\"tab-name\">${esc(tab.name)}</span><button class=\"tab-close\">\u00d7</button>`;\n    el.querySelector('.tab-close').addEventListener('click',e=>{e.stopPropagation();closeTab(tab.id);});\n    el.addEventListener('click',()=>switchTab(tab.id));\n    el.addEventListener('dblclick',()=>openRename(tab.id));\n    bar.insertBefore(el,addBtn);\n  });\n}\nfunction renderApp(){\n  const app=document.getElementById('app');\n  app.querySelectorAll('.pane:not(#pane-online)').forEach(el=>el.remove());\n  tabs.forEach(tab=>{if(!document.getElementById('pane-'+tab.id)){const p=document.createElement('div');p.className='pane';p.id='pane-'+tab.id;app.appendChild(p);}});\n  updateActivePane();\n}\nfunction updateActivePane(){\n  document.querySelectorAll('.pane').forEach(el=>{\n    const isOnline=activeTabId===ONLINE&&el.id==='pane-online';\n    const active=isOnline||(el.id==='pane-'+activeTabId);\n    el.classList.toggle('active',active);\n    if(active&&el.id!=='pane-online'&&!el.children.length){const tab=tabs.find(t=>t.id===activeTabId);if(tab)renderPane(tab);}\n  });\n}\nfunction switchToOnline(){activeTabId=ONLINE;saveTabs();renderTabBar();updateActivePane();}\nfunction switchTab(id){\n  activeTabId=id;saveTabs();\n  document.getElementById('online-tab').classList.remove('active');\n  document.querySelectorAll('.tab-item:not(.pinned)').forEach(el=>el.classList.toggle('active',el.dataset.id===id));\n  document.querySelectorAll('.pane').forEach(el=>{const active=el.id==='pane-'+id;el.classList.toggle('active',active);if(active&&!el.children.length){const tab=tabs.find(t=>t.id===id);if(tab)renderPane(tab);}});\n}\nfunction addTab(){const tab=newTab('\u65b0\u3057\u3044\u30bf\u30d6','');tabs.push(tab);activeTabId=tab.id;saveTabs();const p=document.createElement('div');p.className='pane';p.id='pane-'+tab.id;document.getElementById('app').appendChild(p);renderSetup(p,tab);renderTabBar();updateActivePane();}\nfunction closeTab(id){\n  if(tabs.length===1)return;\n  const idx=tabs.findIndex(t=>t.id===id),tab=tabs[idx];\n  recents.unshift({...tab,deletedAt:Date.now()});if(recents.length>20)recents=recents.slice(0,20);saveRecents();\n  tabs.splice(idx,1);document.getElementById('pane-'+id)?.remove();\n  if(activeTabId===id)activeTabId=tabs[Math.min(idx,tabs.length-1)].id;\n  saveTabs();syncPlaylistsToGitHub();renderTabBar();updateActivePane();\n}\n\n// \u2500\u2500 Playlist panes \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nfunction renderPane(tab){const p=document.getElementById('pane-'+tab.id);if(!p)return;tab.playlistId?renderVideos(p,tab):renderSetup(p,tab);}\nfunction extractPlaylistId(raw){const m=raw.match(/[?&]list=([A-Za-z0-9_-]+)/);return m?m[1]:raw.trim();}\nfunction renderSetup(pane,tab){\n  pane.innerHTML=`<div class=\"setup-box\"><h2>\u30d7\u30ec\u30a4\u30ea\u30b9\u30c8\u3092\u8a2d\u5b9a</h2>\n    <div class=\"field\"><label>\u30bf\u30d6\u540d</label><input type=\"text\" id=\"sn-${tab.id}\" value=\"${esc(tab.name)}\" placeholder=\"\u30bf\u30d6\u540d\"></div>\n    <div class=\"field\"><label>YouTube URL \u307e\u305f\u306f ID</label><input type=\"text\" id=\"sp-${tab.id}\" value=\"${esc(tab.playlistId)}\" placeholder=\"https://youtube.com/... \u3067\u3082OK\"></div>\n    <div class=\"errmsg\" id=\"se-${tab.id}\"></div>\n    <div class=\"btn-row\">\n      <button class=\"btn-accent\" onclick=\"saveTabPlaylist('${tab.id}')\">\u4fdd\u5b58</button>\n      ${tab.playlistId?`<button class=\"btn-outline\" onclick=\"cancelSetup('${tab.id}')\">\u30ad\u30e3\u30f3\u30bb\u30eb</button>`:''}\n    </div></div>`;\n}\nfunction cancelSetup(tabId){const tab=tabs.find(t=>t.id===tabId);const p=document.getElementById('pane-'+tabId);if(tab?.playlistId&&p)renderVideos(p,tab);}\nfunction saveTabPlaylist(tabId){\n  const raw=document.getElementById(`sp-${tabId}`)?.value.trim()||'';\n  const name=document.getElementById(`sn-${tabId}`)?.value.trim()||'';\n  const errEl=document.getElementById(`se-${tabId}`);\n  const plId=extractPlaylistId(raw);\n  if(!plId){if(errEl){errEl.textContent='URL\u307e\u305f\u306fID\u3092\u5165\u529b\u3057\u3066\u304f\u3060\u3055\u3044';errEl.style.display='block';}return;}\n  const tab=tabs.find(t=>t.id===tabId);if(!tab)return;\n  tab.playlistId=plId;if(name)tab.name=name;delete videoCache[tabId];saveTabs();syncPlaylistsToGitHub();renderTabBar();renderPane(tab);\n}\nasync function renderVideos(pane,tab){\n  pane.innerHTML=`<div class=\"vid-header\"><span style=\"font-size:12px;color:var(--accent)\">${esc(tab.name)}</span><span id=\"vc-${tab.id}\" style=\"font-size:10px;color:var(--muted)\"></span><div style=\"flex:1\"></div><button class=\"btn-outline btn-sm\" onclick=\"editTabPlaylist('${tab.id}')\">\u8a2d\u5b9a</button><button class=\"btn-outline btn-sm\" onclick=\"refreshTab('${tab.id}')\">\u66f4\u65b0</button></div><div id=\"vg-${tab.id}\" class=\"loading\">\u8aad\u307f\u8fbc\u307f\u4e2d...</div>`;\n  if(videoCache[tab.id]){renderGrid(tab.id,videoCache[tab.id]);return;}\n  try{\n    const res=await fetch(`${WORKER}/videos?playlistId=${tab.playlistId}`);const data=await res.json();\n    if(data.error)throw new Error(data.error);videoCache[tab.id]=data;renderGrid(tab.id,data);\n  }catch(e){const el=document.getElementById(`vg-${tab.id}`);if(el)el.innerHTML=`<div class=\"empty\">\u30a8\u30e9\u30fc: ${esc(e.message)}</div>`;}\n}\nfunction renderGrid(tabId,videos){\n  const vc=document.getElementById(`vc-${tabId}`),vg=document.getElementById(`vg-${tabId}`);\n  if(vc)vc.textContent=videos.length+'\u672c';if(!vg)return;\n  if(!videos.length){vg.innerHTML='<div class=\"empty\">\u52d5\u753b\u304c\u3042\u308a\u307e\u305b\u3093</div>';return;}\n  vg.className='video-grid';\n  vg.innerHTML=videos.map(v=>`<div class=\"video-card\" onclick=\"location.href='/player.html?v=${v.id}&t=${encodeURIComponent(v.title)}'\"><img src=\"${v.thumb}\" loading=\"lazy\" onerror=\"this.style.background='var(--bg3)'\"><div class=\"vc-title\">${esc(v.title)}</div></div>`).join('');\n}\nfunction editTabPlaylist(tabId){const tab=tabs.find(t=>t.id===tabId);const p=document.getElementById('pane-'+tabId);if(tab&&p)renderSetup(p,tab);}\nasync function refreshTab(tabId){delete videoCache[tabId];const tab=tabs.find(t=>t.id===tabId);const p=document.getElementById('pane-'+tabId);if(tab&&p)renderVideos(p,tab);}\n\n// \u2500\u2500 Rename \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nfunction openRename(id){renameTabId=id;const tab=tabs.find(t=>t.id===id);document.getElementById('rename-input').value=tab?.name||'';document.getElementById('rename-modal').classList.add('open');setTimeout(()=>{document.getElementById('rename-input').focus();document.getElementById('rename-input').select();},50);}\nfunction confirmRename(){const name=document.getElementById('rename-input').value.trim();if(!name||!renameTabId)return closeModal('rename-modal');const tab=tabs.find(t=>t.id===renameTabId);if(tab){tab.name=name;saveTabs();renderTabBar();}closeModal('rename-modal');}\ndocument.getElementById('rename-input').addEventListener('keydown',e=>{if(e.key==='Enter')confirmRename();if(e.key==='Escape')closeModal('rename-modal');});\n\n// \u2500\u2500 Recents \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nfunction toggleRecent(){recentOpen=!recentOpen;document.getElementById('recent-panel').classList.toggle('open',recentOpen);if(recentOpen)renderRecentList();}\nfunction renderRecentList(){\n  const el=document.getElementById('rp-list');\n  if(!recents.length){el.innerHTML='<div class=\"empty\" style=\"padding:16px\">\u524a\u9664\u3057\u305f\u30bf\u30d6\u306f\u3042\u308a\u307e\u305b\u3093</div>';return;}\n  el.innerHTML=recents.map((r,i)=>`<div class=\"recent-item\"><div class=\"ri-info\"><div class=\"ri-name\">${esc(r.name)}</div><div class=\"ri-pl\">${esc(r.playlistId||'\u672a\u8a2d\u5b9a')}</div><div class=\"ri-time\">${fmtTime(r.deletedAt)}</div></div><button class=\"btn-accent btn-sm\" onclick=\"restoreTab(${i})\">\u5fa9\u5143</button></div>`).join('');\n}\nfunction restoreTab(idx){\n  const r=recents[idx];if(!r)return;\n  const tab={...newTab(r.name,r.playlistId)};tabs.push(tab);recents.splice(idx,1);saveRecents();saveTabs();syncPlaylistsToGitHub();\n  const p=document.createElement('div');p.className='pane';p.id='pane-'+tab.id;document.getElementById('app').appendChild(p);\n  renderTabBar();renderRecentList();\n}\n\n// \u2500\u2500 Sync \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nasync function syncPlaylistsToGitHub(){\n  const pl=tabs.filter(t=>t.playlistId).map(t=>({id:t.playlistId,title:t.name,autoDownload:false}));\n  if(!pl.length)return;\n  try{await fetch(`${WORKER}/playlists`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({playlists:pl})});}catch{}\n}\n\n// \u2500\u2500 Push \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nasync function togglePush(){\n  if(!swReg){alert('Service Worker\u304c\u5229\u7528\u3067\u304d\u307e\u305b\u3093');return;}\n  if(pushSub){await pushSub.unsubscribe();pushSub=null;updatePushBadge();updatePushDebug();return;}\n  const perm=await Notification.requestPermission();if(perm!=='granted'){alert('\u30d6\u30e9\u30a6\u30b6\u306e\u8a2d\u5b9a\u3067\u901a\u77e5\u3092\u8a31\u53ef\u3057\u3066\u304f\u3060\u3055\u3044');return;}\n  if(!VAPID){alert('VAPID_PUBLIC\u304cWorker\u306b\u8a2d\u5b9a\u3055\u308c\u3066\u3044\u307e\u305b\u3093');return;}\n  try{\n    await navigator.serviceWorker.ready;\n    pushSub=await swReg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:urlB64ToUint8(VAPID)});\n    const res=await fetch(`${WORKER}/subscribe`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({subscription:pushSub.toJSON()})});\n    if(!res.ok)throw new Error(`Worker: ${res.status}`);\n    updatePushBadge();updatePushDebug();\n  }catch(e){alert('\u767b\u9332\u30a8\u30e9\u30fc: '+e.message);}\n}\nfunction updatePushBadge(){const on=!!pushSub;document.getElementById('push-badge').textContent=on?'PUSH ON':'PUSH OFF';document.getElementById('push-badge').className=on?'badge':'badge off';}\nfunction updatePushDebug(){const el=document.getElementById('push-debug');if(!el)return;el.textContent=pushSub?'\u767b\u9332\u6e08: '+pushSub.endpoint.slice(0,50)+'...':'\u672a\u767b\u9332';}\nasync function testLocalNotif(){\n  const perm=await Notification.requestPermission();if(perm!=='granted'){alert('\u901a\u77e5\u3092\u8a31\u53ef\u3057\u3066\u304f\u3060\u3055\u3044');return;}\n  if(swReg)await swReg.showNotification('\u30c6\u30b9\u30c8\u901a\u77e5',{body:'\u901a\u77e5\u304c\u6b63\u5e38\u306b\u5c4a\u3044\u3066\u3044\u307e\u3059',tag:'test'});\n  else new Notification('\u30c6\u30b9\u30c8\u901a\u77e5',{body:'\u901a\u77e5\u304c\u5c4a\u3044\u3066\u3044\u307e\u3059'});\n}\n\n// \u2500\u2500 Notifications \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nfunction toggleNotifPanel(){notifOpen=!notifOpen;document.getElementById('notif-panel').classList.toggle('open',notifOpen);if(notifOpen)renderNotifList();}\nfunction renderNotifList(){\n  const el=document.getElementById('np-list');\n  const hdr=`<div style=\"padding:8px;border-bottom:1px solid var(--border)\"><button class=\"btn-outline btn-sm\" onclick=\"testLocalNotif()\" style=\"width:100%;margin-bottom:6px\">\u901a\u77e5\u30c6\u30b9\u30c8</button><div id=\"push-debug\" style=\"font-size:10px;color:var(--muted);line-height:1.6;word-break:break-all\"></div></div>`;\n  if(!notifs.length){el.innerHTML=hdr+'<div class=\"empty\" style=\"padding:16px\">\u901a\u77e5\u306f\u3042\u308a\u307e\u305b\u3093</div>';updatePushDebug();return;}\n  el.innerHTML=hdr+notifs.map(n=>`<div class=\"notif-item\"><div class=\"ni-title\">${esc(n.title)}</div><div class=\"ni-body\">${esc(n.body)}</div>${n.url?`<a class=\"ni-link\" href=\"${n.url}\" target=\"_blank\">\u25b6 \u958b\u304f</a>`:''}<div class=\"ni-time\">${fmtTime(n.time)}</div></div>`).join('');\n  updatePushDebug();\n}\nfunction clearNotifs(){notifs=[];localStorage.setItem('yt_notifs','[]');updateNotifBadge();renderNotifList();}\nfunction updateNotifBadge(){document.getElementById('notif-badge').textContent=notifs.length+'\u4ef6';document.getElementById('notif-badge').className=notifs.length?'badge warn':'badge off';}\nnavigator.serviceWorker?.addEventListener('message',e=>{\n  if(e.data?.type==='push'){notifs.unshift({...e.data,time:new Date().toISOString()});if(notifs.length>50)notifs=notifs.slice(0,50);localStorage.setItem('yt_notifs',JSON.stringify(notifs));updateNotifBadge();if(notifOpen)renderNotifList();}\n});\n\n// \u2500\u2500 Helpers \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nfunction closeModal(id){document.getElementById(id).classList.remove('open');}\nconst esc=s=>String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\"/g,'&quot;');\nconst fmtTime=ts=>{const d=new Date(ts);return`${d.getMonth()+1}/${d.getDate()} ${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`;};\nfunction urlB64ToUint8(b){const pad='='.repeat((4-b.length%4)%4);const raw=atob((b+pad).replace(/-/g,'+').replace(/_/g,'/'));return Uint8Array.from([...raw].map(c=>c.charCodeAt(0)));}\n</script>\n</body>\n</html>\n";

const PLAYER_HTML = "<!DOCTYPE html>\n<html lang=\"ja\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1.0\">\n<title>Player</title>\n<script src=\"https://www.youtube.com/iframe_api\"></script>\n<style>\n*{margin:0;padding:0;box-sizing:border-box;-webkit-user-select:none;user-select:none;-webkit-touch-callout:none}\nhtml,body{width:100%;height:100%;overflow:hidden;background:#000;font-family:Inter,system-ui,sans-serif}\nbody{background:radial-gradient(circle at top left,#3d003d,transparent 30%),radial-gradient(circle at bottom right,#001a3d,transparent 30%),#050505}\n.player-shell{position:fixed;inset:0;display:flex;justify-content:center;align-items:center;padding:20px}\n.player-wrap{position:relative;width:min(1600px,96vw);aspect-ratio:16/9;overflow:hidden;border-radius:34px;background:#000;box-shadow:0 30px 100px rgba(0,0,0,.8),inset 0 0 0 1px rgba(255,255,255,.05);touch-action:manipulation}\n#player{position:absolute;inset:-14%;width:128%;height:128%;pointer-events:none;filter:contrast(1.04) saturate(1.08)}\n.ui{position:absolute;inset:0;z-index:20;display:flex;flex-direction:column;justify-content:space-between;background:linear-gradient(to top,rgba(0,0,0,.92),rgba(0,0,0,.25) 30%,transparent 60%);opacity:0;transition:.25s}\n.player-wrap:hover .ui,.player-wrap.show-ui .ui{opacity:1}\n.topbar{padding:28px;display:flex;justify-content:space-between;align-items:flex-start;gap:20px}\n.back-btn{background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.15);border-radius:999px;color:#fff;cursor:pointer;padding:8px 16px;font-size:14px;display:flex;align-items:center;gap:6px;backdrop-filter:blur(10px);flex-shrink:0}\n.back-btn:hover{background:rgba(255,255,255,.18)}\n.title-block{flex:1;min-width:0}\n.title{font-size:20px;font-weight:700;color:#fff;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.sub{opacity:.5;margin-top:4px;color:#fff;font-size:13px}\n.status{padding:10px 16px;border-radius:999px;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.08);backdrop-filter:blur(20px);font-size:13px;letter-spacing:.08em;opacity:.85;transition:.2s;color:#fff;white-space:nowrap;flex-shrink:0}\n.status.fast{background:rgba(255,0,80,.16);border:1px solid rgba(255,0,80,.35);box-shadow:0 0 30px rgba(255,0,80,.2);color:#ff7ba5}\n.center{flex:1;display:flex;justify-content:center;align-items:center;min-height:0}\n.bigplay{width:120px;height:120px;border-radius:999px;backdrop-filter:blur(20px);background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.08);display:flex;justify-content:center;align-items:center;cursor:pointer;transition:.25s;font-size:42px;color:#fff}\n.bigplay:hover{transform:scale(1.08)}\n.bottom{padding:28px}\n.progress-area{width:100%;height:8px;border-radius:999px;background:rgba(255,255,255,.12);overflow:visible;cursor:pointer;position:relative}\n.progress-area::before{content:'';position:absolute;top:-14px;left:0;right:0;bottom:-14px}\n.progress{width:0%;height:100%;border-radius:999px;background:linear-gradient(90deg,#ff0055,#ff4d7d)}\n.preview{position:absolute;bottom:22px;left:0;transform:translateX(-50%);width:220px;border-radius:18px;overflow:hidden;background:rgba(10,10,10,.95);border:1px solid rgba(255,255,255,.08);backdrop-filter:blur(20px);opacity:0;transition:.12s;pointer-events:none;z-index:500}\n.preview.show{opacity:1}\n.preview img{width:100%;aspect-ratio:16/9;object-fit:cover;display:block;background:#000}\n.previewTime{padding:10px;font-size:13px;text-align:center;background:rgba(255,255,255,.04);color:#fff}\n.controls{margin-top:20px;display:flex;justify-content:space-between;align-items:center}\n.left,.right{display:flex;align-items:center;gap:10px}\n.btn{width:auto;min-width:48px;height:48px;padding:0 16px;border-radius:16px;border:none;background:rgba(255,255,255,.08);color:#fff;cursor:pointer;transition:.2s;font-size:15px;display:flex;justify-content:center;align-items:center;gap:8px;backdrop-filter:blur(10px)}\n.btn:hover{transform:translateY(-2px);background:rgba(255,255,255,.14)}\n.icon-btn{padding:0;width:48px}\n.icon-btn svg{width:22px;height:22px;fill:#fff;display:block}\n.time{opacity:.7;font-size:14px;color:#fff}\n.volume{width:100px;accent-color:#ff3366}\n.speed{background:rgba(255,255,255,.08);color:#fff;border:none;height:42px;border-radius:12px;padding:0 12px;outline:none;font-size:14px}\n.speed option{background:#111}\n.settings{position:absolute;right:20px;bottom:95px;width:220px;background:rgba(15,15,15,.95);border:1px solid rgba(255,255,255,.08);border-radius:20px;padding:18px;z-index:100;backdrop-filter:blur(20px);display:none}\n.settings.active{display:block}\n.settings h3{margin-bottom:14px;font-size:16px;color:#fff}\n.settings-row{margin-bottom:14px}\n.settings-row label{display:block;margin-bottom:8px;opacity:.7;font-size:13px;color:#fff}\n.edge-mask-top{position:absolute;top:0;left:0;width:100%;height:90px;background:linear-gradient(to bottom,rgba(0,0,0,.95),transparent);z-index:11}\n.edge-mask-right{position:absolute;top:0;right:0;width:130px;height:100%;background:linear-gradient(to left,rgba(0,0,0,.95),transparent);z-index:11}\n.edge-mask-bottom{position:absolute;bottom:0;left:0;width:100%;height:90px;background:linear-gradient(to top,rgba(0,0,0,.95),transparent);z-index:11}\n.loader{position:absolute;inset:0;display:flex;justify-content:center;align-items:center;z-index:50;backdrop-filter:blur(10px);background:rgba(0,0,0,.6);transition:.4s}\n.spinner{width:70px;height:70px;border-radius:50%;border:4px solid rgba(255,255,255,.15);border-top:4px solid #fff;animation:spin 1s linear infinite}\n@keyframes spin{to{transform:rotate(360deg)}}\n.hide{opacity:0;pointer-events:none}\n.skip-popup{position:absolute;top:50%;transform:translateY(-50%);padding:16px 24px;border-radius:20px;background:rgba(0,0,0,.72);backdrop-filter:blur(20px);font-size:22px;font-weight:700;opacity:0;transition:.2s;pointer-events:none;z-index:200;display:flex;align-items:center;gap:10px;color:#fff}\n.skip-popup.show{opacity:1}\n.skip-left{left:60px}\n.skip-right{right:60px}\n.skip-popup svg{width:28px;height:28px;fill:#fff;flex:none}\n@media(max-width:640px){\n  .player-shell{padding:0}\n  .player-wrap{width:100vw;border-radius:0}\n  .topbar{padding:10px 14px;gap:8px}\n  .title{font-size:13px}\n  .sub{font-size:10px;margin-top:2px}\n  .status{font-size:10px;padding:5px 10px}\n  .back-btn{padding:6px 10px;font-size:12px}\n  .bigplay{width:56px;height:56px;font-size:20px}\n  .bottom{padding:10px 14px}\n  .controls{margin-top:10px}\n  .btn{min-width:34px;height:34px;padding:0 10px;border-radius:10px;font-size:12px}\n  .icon-btn{width:34px;padding:0}\n  .icon-btn svg{width:16px;height:16px}\n  .volume{display:none}\n  .time{font-size:11px}\n  .left,.right{gap:6px}\n  .settings{right:8px;bottom:78px;width:calc(100% - 16px);max-width:220px}\n  .skip-left{left:20px}\n  .skip-right{right:20px}\n  .skip-popup{padding:10px 16px;font-size:16px;border-radius:14px}\n  .skip-popup svg{width:20px;height:20px}\n}\n</style>\n</head>\n<body>\n<div class=\"player-shell\">\n<div class=\"player-wrap\" id=\"wrap\">\n  <div class=\"edge-mask-top\"></div>\n  <div class=\"edge-mask-right\"></div>\n  <div class=\"edge-mask-bottom\"></div>\n  <div id=\"player\"></div>\n  <div class=\"skip-popup skip-left\" id=\"skipLeft\"><svg viewBox=\"0 0 24 24\"><path d=\"M11 18V6L2.5 12zm9 0V6l-8.5 6z\"/></svg><span>15s</span></div>\n  <div class=\"skip-popup skip-right\" id=\"skipRight\"><span>15s</span><svg viewBox=\"0 0 24 24\"><path d=\"M4 18l8.5-6L4 6zm9 0l8.5-6L13 6z\"/></svg></div>\n  <div class=\"loader\" id=\"loader\"><div class=\"spinner\"></div></div>\n  <div class=\"settings\" id=\"settings\">\n    <h3>Settings</h3>\n    <div class=\"settings-row\">\n      <label>Playback Speed</label>\n      <select class=\"speed\" id=\"speed\">\n        <option value=\"0.25\">0.25x</option><option value=\"0.5\">0.5x</option>\n        <option value=\"0.75\">0.75x</option><option value=\"1\" selected>1x</option>\n        <option value=\"1.25\">1.25x</option><option value=\"1.5\">1.5x</option>\n        <option value=\"1.75\">1.75x</option><option value=\"2\">2x</option>\n      </select>\n    </div>\n  </div>\n  <div class=\"ui\">\n    <div class=\"topbar\">\n      <button class=\"back-btn\" onclick=\"history.back()\">&#8592; \u623b\u308b</button>\n      <div class=\"title-block\">\n        <div class=\"title\" id=\"vidTitle\">Loading...</div>\n        <div class=\"sub\" id=\"vidSub\"></div>\n      </div>\n      <div class=\"status\" id=\"status\">NORMAL</div>\n    </div>\n    <div class=\"center\"><div class=\"bigplay\" id=\"bigplay\">\u25b6</div></div>\n    <div class=\"bottom\">\n      <div class=\"progress-area\" id=\"progressArea\">\n        <div class=\"progress\" id=\"progress\"></div>\n        <div class=\"preview\" id=\"preview\">\n          <img id=\"previewImg\">\n          <div class=\"previewTime\" id=\"previewTime\">0:00</div>\n        </div>\n      </div>\n      <div class=\"controls\">\n        <div class=\"left\">\n          <button class=\"btn icon-btn\" id=\"play\"><svg id=\"playSvg\" viewBox=\"0 0 24 24\"><path d=\"M8 5v14l11-7z\"/></svg></button>\n          <button class=\"btn icon-btn\" id=\"mute\"><svg id=\"muteSvg\" viewBox=\"0 0 24 24\"><path d=\"M3 10v4h4l5 5V5L7 10z\"/></svg></button>\n          <input class=\"volume\" type=\"range\" min=\"0\" max=\"100\" value=\"100\" id=\"volume\">\n          <div class=\"time\" id=\"time\">0:00 / 0:00</div>\n        </div>\n        <div class=\"right\">\n          <button class=\"btn\" id=\"settingsBtn\">Settings</button>\n          <button class=\"btn icon-btn\" id=\"fullscreen\"><svg viewBox=\"0 0 24 24\"><path d=\"M7 14H5v5h5v-2H7zm0-4h2V7h3V5H5v5zm10 7h-3v2h5v-5h-2zm0-12V5h-5v2h3v3h2z\"/></svg></button>\n        </div>\n      </div>\n    </div>\n  </div>\n</div>\n</div>\n<script>\ndocument.addEventListener('contextmenu', e => e.preventDefault());\n\n// \u2500\u2500 URL params \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nconst params  = new URLSearchParams(location.search);\nconst videoId = params.get('v') || 'dQw4w9WgXcQ';\nconst title   = decodeURIComponent(params.get('t') || '');\ndocument.getElementById('vidTitle').textContent = title || 'YouTube Player';\ndocument.title = title || 'Player';\n\nlet player, playing = false;\nlet holdTimeout, holdSpeeding = false, prevSpeed = 1;\nlet lastTap = 0, lastSide = '', previewTimer;\nlet dragging = false, isDraggingProgress = false;\nlet ignoreWrapClick = false, justClosedSettings = false;\nlet uiTimeout, isHolding = false;\nlet touchStartX = 0, touchStartY = 0;\n\nconst loader = document.getElementById('loader');\nconst wrap = document.getElementById('wrap');\nconst progress = document.getElementById('progress');\nconst progressArea = document.getElementById('progressArea');\nconst time = document.getElementById('time');\nconst play = document.getElementById('play');\nconst mute = document.getElementById('mute');\nconst volume = document.getElementById('volume');\nconst fullscreen = document.getElementById('fullscreen');\nconst bigplay = document.getElementById('bigplay');\nconst settingsBtn = document.getElementById('settingsBtn');\nconst settings = document.getElementById('settings');\nconst speed = document.getElementById('speed');\nconst statusBox = document.getElementById('status');\nconst skipLeft = document.getElementById('skipLeft');\nconst skipRight = document.getElementById('skipRight');\nconst preview = document.getElementById('preview');\nconst previewImg = document.getElementById('previewImg');\nconst previewTime = document.getElementById('previewTime');\nconst playSvg = document.getElementById('playSvg');\nconst muteSvg = document.getElementById('muteSvg');\n\nfunction onYouTubeIframeAPIReady() {\n  player = new YT.Player('player', {\n    videoId,\n    playerVars: { autoplay: 1, controls: 0, disablekb: 1, fs: 0, rel: 0, modestbranding: 1, playsinline: 1, iv_load_policy: 3, cc_load_policy: 0, enablejsapi: 1 },\n    events: { onReady: onReady }\n  });\n}\n\nfunction onReady() {\n  loader.classList.add('hide');\n  playing = true;\n  playSvg.innerHTML = '<path d=\"M6 5h4v14H6zm8 0h4v14h-4z\"/>';\n  bigplay.innerHTML = '\u2161';\n  updateLoop();\n}\n\nfunction showUI() {\n  wrap.classList.add('show-ui');\n  clearTimeout(uiTimeout);\n  uiTimeout = setTimeout(() => {\n    if (!settings.classList.contains('active')) wrap.classList.remove('show-ui');\n  }, 2500);\n}\n['mousemove','touchstart','click','keydown'].forEach(ev => document.addEventListener(ev, showUI));\n\nfunction updateLoop() {\n  setInterval(() => {\n    if (!player?.getDuration) return;\n    if (isDraggingProgress) return;\n    const cur = player.getCurrentTime();\n    const dur = player.getDuration();\n    progress.style.width = (cur / dur * 100) + '%';\n    time.innerText = format(cur) + ' / ' + format(dur);\n  }, 150);\n}\n\nfunction playVideo()  { player.playVideo();  playing = true;  playSvg.innerHTML = '<path d=\"M6 5h4v14H6zm8 0h4v14h-4z\"/>'; bigplay.innerHTML = '\u2161'; }\nfunction pauseVideo() { player.pauseVideo(); playing = false; playSvg.innerHTML = '<path d=\"M8 5v14l11-7z\"/>'; bigplay.innerHTML = '\u25b6'; }\nfunction togglePlay() { playing ? pauseVideo() : playVideo(); }\n\nplay.addEventListener('click', e => { e.stopPropagation(); ignoreWrapClick = true; togglePlay(); setTimeout(() => { ignoreWrapClick = false; }, 50); });\nbigplay.addEventListener('click', e => { e.stopPropagation(); ignoreWrapClick = true; togglePlay(); setTimeout(() => { ignoreWrapClick = false; }, 50); });\n\nwrap.addEventListener('click', e => {\n  if (isHolding || ignoreWrapClick || isDraggingProgress || holdSpeeding) return;\n  if (justClosedSettings) { justClosedSettings = false; return; }\n  if (settings.classList.contains('active') && !settings.contains(e.target) && !settingsBtn.contains(e.target)) {\n    settings.classList.remove('active'); justClosedSettings = true; return;\n  }\n  if (settings.contains(e.target) || settingsBtn.contains(e.target) || progressArea.contains(e.target) || e.target.closest('.btn') || e.target.closest('.speed') || e.target.closest('.volume') || e.target.closest('.back-btn')) return;\n  const now = Date.now();\n  const rect = wrap.getBoundingClientRect();\n  const x = e.clientX - rect.left;\n  const side = x < rect.width / 2 ? 'left' : 'right';\n  if (now - lastTap < 300 && side === lastSide) {\n    clearTimeout(previewTimer);\n    if (side === 'left') { player.seekTo(player.getCurrentTime() - 15, true); showSkip(skipLeft); }\n    else { player.seekTo(player.getCurrentTime() + 15, true); showSkip(skipRight); }\n    lastTap = 0; return;\n  }\n  clearTimeout(previewTimer);\n  previewTimer = setTimeout(() => { if (!holdSpeeding && !isDraggingProgress) togglePlay(); }, 310);\n  lastTap = now; lastSide = side;\n});\n\nfunction showSkip(el) { el.classList.add('show'); setTimeout(() => el.classList.remove('show'), 450); }\n\nfunction startHold(e) {\n  if (e.target.closest('.controls') || e.target.closest('.settings') || e.target.closest('.progress-area') || e.target.closest('.back-btn')) return;\n  if (e.touches) { touchStartX = e.touches[0].clientX; touchStartY = e.touches[0].clientY; }\n  isHolding = true;\n  holdTimeout = setTimeout(() => {\n    holdSpeeding = true; prevSpeed = player.getPlaybackRate();\n    player.setPlaybackRate(2); updateStatus(2);\n  }, 500);\n}\nfunction stopHold() {\n  clearTimeout(holdTimeout);\n  if (holdSpeeding) { holdSpeeding = false; player.setPlaybackRate(prevSpeed); updateStatus(prevSpeed); ignoreWrapClick = true; setTimeout(() => { ignoreWrapClick = false; }, 200); }\n  isHolding = false;\n}\nwrap.addEventListener('mousedown', startHold);\nwrap.addEventListener('mouseup', stopHold);\nwrap.addEventListener('mouseleave', stopHold);\nwrap.addEventListener('touchstart', startHold, { passive: true });\nwrap.addEventListener('touchend', stopHold);\nwrap.addEventListener('touchcancel', stopHold);\nwrap.addEventListener('touchmove', e => {\n  if (!isHolding || holdSpeeding) return;\n  const dx = e.touches[0].clientX - touchStartX, dy = e.touches[0].clientY - touchStartY;\n  if (Math.sqrt(dx*dx + dy*dy) > 10) { clearTimeout(holdTimeout); isHolding = false; }\n}, { passive: true });\n\nmute.onclick = () => {\n  if (player.isMuted()) { player.unMute(); muteSvg.innerHTML = '<path d=\"M3 10v4h4l5 5V5L7 10z\"/>'; }\n  else { player.mute(); muteSvg.innerHTML = '<path d=\"M16 9l5 5m0-5l-5 5M3 10v4h4l5 5V5L7 10z\" stroke=\"white\" stroke-width=\"2\" fill=\"none\" stroke-linecap=\"round\"/>'; }\n};\nvolume.oninput = e => player.setVolume(e.target.value);\n\nfunction seekFromEvent(e) {\n  const rect = progressArea.getBoundingClientRect();\n  const clientX = e.touches ? e.touches[0].clientX : e.clientX;\n  const per = Math.max(0, Math.min(1, (clientX - rect.left) / rect.width));\n  const seekTime = player.getDuration() * per;\n  progress.style.width = (per * 100) + '%';\n  time.innerText = format(seekTime) + ' / ' + format(player.getDuration());\n  player.seekTo(seekTime, true);\n}\nprogressArea.addEventListener('mousedown', e => { e.stopPropagation(); isDraggingProgress = true; seekFromEvent(e); });\ndocument.addEventListener('mousemove', e => { if (isDraggingProgress) seekFromEvent(e); });\ndocument.addEventListener('mouseup', () => { if (isDraggingProgress) setTimeout(() => { isDraggingProgress = false; }, 20); });\nprogressArea.addEventListener('touchstart', e => { showUI(); e.stopPropagation(); isDraggingProgress = true; seekFromEvent(e); }, { passive: false });\ndocument.addEventListener('touchmove', e => { if (isDraggingProgress) seekFromEvent(e); }, { passive: true });\ndocument.addEventListener('touchend', () => { if (isDraggingProgress) setTimeout(() => { isDraggingProgress = false; }, 20); });\n\nprogressArea.addEventListener('mousemove', e => {\n  const rect = progressArea.getBoundingClientRect();\n  const x = e.clientX - rect.left;\n  const per = Math.max(0, Math.min(1, x / rect.width));\n  preview.classList.add('show'); preview.style.left = x + 'px';\n  previewTime.innerHTML = format(player.getDuration() * per);\n  previewImg.src = `https://i.ytimg.com/sb/${videoId}/storyboard3_L2/M${Math.floor(player.getDuration() * per / 5)}.jpg`;\n});\nprogressArea.addEventListener('mouseleave', () => preview.classList.remove('show'));\n\nfullscreen.onclick = async () => {\n  if (!document.fullscreenElement) {\n    await wrap.requestFullscreen();\n    try { await screen.orientation?.lock('landscape'); } catch {}\n  } else { document.exitFullscreen(); }\n};\n\nsettingsBtn.onclick = e => { e.stopPropagation(); settings.classList.toggle('active'); };\nspeed.onchange = e => { const v = Number(e.target.value); player.setPlaybackRate(v); updateStatus(v); };\n\nfunction updateStatus(s) {\n  if (s === 1) { statusBox.innerHTML = 'NORMAL'; statusBox.classList.remove('fast'); }\n  else { statusBox.innerHTML = `${s}x SPEED`; statusBox.classList.add('fast'); }\n}\n\ndocument.addEventListener('keydown', e => {\n  if (e.code === 'Space') { e.preventDefault(); togglePlay(); }\n  if (e.code === 'ArrowRight') player.seekTo(player.getCurrentTime() + 5, true);\n  if (e.code === 'ArrowLeft')  player.seekTo(player.getCurrentTime() - 5, true);\n  if (e.code === 'KeyM') mute.click();\n  if (e.code === 'KeyF') fullscreen.click();\n});\n\nfunction format(sec) {\n  sec = Math.floor(sec || 0);\n  return Math.floor(sec / 60) + ':' + String(sec % 60).padStart(2, '0');\n}\n</script>\n</body>\n</html>\n";

const SW_JS = "const CACHE = 'yt-watcher-v3';\n\nself.addEventListener('install', e => {\n  e.waitUntil(\n    caches.open(CACHE)\n      .then(c => c.addAll(['/yt-watcher/', '/yt-watcher/index.html', '/yt-watcher/manifest.json']))\n      .catch(() => {}) // \u30ad\u30e3\u30c3\u30b7\u30e5\u5931\u6557\u3057\u3066\u3082OK\n  );\n  self.skipWaiting();\n});\n\nself.addEventListener('activate', e => {\n  e.waitUntil(\n    caches.keys().then(keys =>\n      Promise.all(keys.filter(k => k !== CACHE).map(k => caches.delete(k)))\n    )\n  );\n  self.clients.claim();\n});\n\nself.addEventListener('fetch', e => {\n  if (e.request.method !== 'GET') return;\n  if (e.request.url.includes('workers.dev')) return;\n  e.respondWith(\n    fetch(e.request).then(res => {\n      const clone = res.clone();\n      caches.open(CACHE).then(c => c.put(e.request, clone)).catch(() => {});\n      return res;\n    }).catch(() => caches.match(e.request))\n  );\n});\n\n// \u2500\u2500 Push notification \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nself.addEventListener('push', e => {\n  let data = {};\n  try { data = e.data.json(); } catch { try { data = { title: 'YT Watcher', body: e.data.text() }; } catch {} }\n\n  const title = data.title || 'YT Watcher';\n  const body  = data.body  || '';\n  const url   = data.url   || '/yt-watcher/';\n\n  e.waitUntil(Promise.all([\n    self.registration.showNotification(title, {\n      body,\n      badge: '/yt-watcher/manifest.json', // icon\u4e0d\u8981\u30fbbadge\u3060\u3051\n      tag:   'yt-' + (data.type || 'new'),\n      renotify: true,\n      data:  { url }\n    }),\n    self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then(clients => {\n      clients.forEach(c => c.postMessage({ type: 'push', title, body, url }));\n    })\n  ]));\n});\n\nself.addEventListener('notificationclick', e => {\n  e.notification.close();\n  const url = e.notification.data?.url || '/yt-watcher/';\n  e.waitUntil(\n    clients.matchAll({ type: 'window', includeUncontrolled: true }).then(cls => {\n      for (const c of cls) {\n        if (c.url.includes('/yt-watcher') && 'focus' in c) return c.focus();\n      }\n      return clients.openWindow(url);\n    })\n  );\n});\n";

const MANIFEST_JSON = "{\n  \"name\": \"YT Watcher\",\n  \"short_name\": \"YT Watch\",\n  \"description\": \"YouTube\u30d7\u30ec\u30a4\u30ea\u30b9\u30c8\u76e3\u8996\u30fb\u30aa\u30f3\u30e9\u30a4\u30f3\u901a\u77e5PWA\",\n  \"start_url\": \"/yt-watcher/\",\n  \"scope\": \"/yt-watcher/\",\n  \"display\": \"standalone\",\n  \"background_color\": \"#0a0a0f\",\n  \"theme_color\": \"#7fffb2\",\n  \"orientation\": \"portrait-primary\",\n  \"icons\": []\n}\n";


function injectConfig(html, env) {
  const cfg = JSON.stringify({
    worker: '',
    vapid:  env.VAPID_PUBLIC || '',
  });
  return html.replace('</head>', `<script>window.__CFG=${cfg};<\/script></head>`);
}

const CORS = {
  'Access-Control-Allow-Origin':  '*',
  'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
  'Access-Control-Allow-Headers': 'Content-Type',
};

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const method = request.method;

    if (method === 'OPTIONS') return new Response(null, { headers: CORS });

    if (method === 'GET') {
      const p = url.pathname;

      if (p === '/' || p === '/index.html')
        return htmlRes(injectConfig(INDEX_HTML, env));

      if (p === '/player.html')
        return htmlRes(PLAYER_HTML);

      if (p === '/sw.js')
        return new Response(SW_JS, {
          headers: {
            'Content-Type': 'application/javascript; charset=utf-8',
            'Service-Worker-Allowed': '/',
            'Cache-Control': 'no-cache',
          }
        });

      if (p === '/manifest.json')
        return new Response(MANIFEST_JSON, {
          headers: { 'Content-Type': 'application/manifest+json; charset=utf-8' }
        });

      if (p === '/videos') {
        const plId = url.searchParams.get('playlistId');
        if (!plId) return apiJson({ error: 'Missing playlistId' }, 400);
        try { return apiJson(await fetchPlaylistVideos(plId, env.YT_API_KEY)); }
        catch (e) { return apiJson({ error: e.message }, 500); }
      }

      // Authenticated KV reads for check.py
      if (p === '/subscriptions' || p === '/playlists' || p === '/schedules') {
        if (url.searchParams.get('secret') !== env.API_SECRET)
          return apiJson({ error: 'Unauthorized' }, 401);
        const key = p === '/subscriptions' ? 'push_subscriptions'
                  : p === '/playlists'     ? 'playlists'
                                           : 'schedules';
        try {
          const raw = await env.KV_BINDING.get(key);
          return apiJson(raw ? JSON.parse(raw) : []);
        } catch (e) { return apiJson({ error: e.message }, 500); }
      }
    }

    // POST /subscribe
    if (method === 'POST' && url.pathname === '/subscribe') {
      try {
        const { subscription } = await request.json();
        if (!subscription?.endpoint) return apiJson({ error: 'Missing subscription' }, 400);
        let subs = await getKV(env, 'push_subscriptions', []);
        subs = subs.filter(s => s.endpoint !== subscription.endpoint);
        subs.push(subscription);
        await env.KV_BINDING.put('push_subscriptions', JSON.stringify(subs));
        return apiJson({ ok: true, total: subs.length });
      } catch (e) { return apiJson({ error: e.message }, 500); }
    }

    // POST /unsubscribe
    if (method === 'POST' && url.pathname === '/unsubscribe') {
      try {
        const { endpoint } = await request.json();
        let subs = await getKV(env, 'push_subscriptions', []);
        subs = subs.filter(s => s.endpoint !== endpoint);
        await env.KV_BINDING.put('push_subscriptions', JSON.stringify(subs));
        return apiJson({ ok: true, total: subs.length });
      } catch (e) { return apiJson({ error: e.message }, 500); }
    }

    // POST /playlists
    if (method === 'POST' && url.pathname === '/playlists') {
      try {
        const { playlists } = await request.json();
        if (!Array.isArray(playlists)) return apiJson({ error: 'invalid' }, 400);
        await env.KV_BINDING.put('playlists', JSON.stringify(playlists));
        return apiJson({ ok: true });
      } catch (e) { return apiJson({ error: e.message }, 500); }
    }

    // POST /schedules — sync schedules from client
    if (method === 'POST' && url.pathname === '/schedules') {
      try {
        const { schedules } = await request.json();
        if (!Array.isArray(schedules)) return apiJson({ error: 'invalid' }, 400);
        await env.KV_BINDING.put('schedules', JSON.stringify(schedules));
        return apiJson({ ok: true, count: schedules.length });
      } catch (e) { return apiJson({ error: e.message }, 500); }
    }

    // POST / — legacy subscribe
    if (method === 'POST' && url.pathname === '/') {
      try {
        const { subscription } = await request.json();
        if (!subscription?.endpoint) return apiJson({ error: 'Missing subscription' }, 400);
        let subs = await getKV(env, 'push_subscriptions', []);
        subs = subs.filter(s => s.endpoint !== subscription.endpoint);
        subs.push(subscription);
        await env.KV_BINDING.put('push_subscriptions', JSON.stringify(subs));
        return apiJson({ ok: true, total: subs.length });
      } catch (e) { return apiJson({ error: e.message }, 500); }
    }

    // POST /update-playlists — legacy
    if (method === 'POST' && url.pathname === '/update-playlists') {
      try {
        const { playlists } = await request.json();
        if (Array.isArray(playlists))
          await env.KV_BINDING.put('playlists', JSON.stringify(playlists));
        return apiJson({ ok: true });
      } catch (e) { return apiJson({ error: e.message }, 500); }
    }

    return htmlRes(injectConfig(INDEX_HTML, env));
  }
};

// ── Helpers ───────────────────────────────────────────────────────────────────
async function getKV(env, key, fallback) {
  try {
    const raw = await env.KV_BINDING.get(key);
    if (!raw) return fallback;
    const v = JSON.parse(raw);
    return Array.isArray(v) ? v : fallback;
  } catch { return fallback; }
}

function htmlRes(content) {
  return new Response(content, {
    headers: { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-cache' }
  });
}

function apiJson(data, status = 200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: { ...CORS, 'Content-Type': 'application/json' }
  });
}

async function fetchPlaylistVideos(playlistId, apiKey) {
  const videos = []; let pageToken = '';
  do {
    const u = `https://www.googleapis.com/youtube/v3/playlistItems?part=snippet&maxResults=50&playlistId=${playlistId}&key=${apiKey}${pageToken ? '&pageToken=' + pageToken : ''}`;
    const r = await fetch(u);
    if (!r.ok) throw new Error(`YouTube API: ${r.status}`);
    const data = await r.json();
    if (data.error) throw new Error(data.error.message);
    for (const item of (data.items || [])) {
      const s = item.snippet;
      if (!s?.resourceId?.videoId) continue;
      if (s.title === 'Deleted video' || s.title === 'Private video') continue;
      videos.push({
        id:    s.resourceId.videoId,
        title: s.title,
        thumb: s.thumbnails?.medium?.url || s.thumbnails?.default?.url || '',
      });
    }
    pageToken = data.nextPageToken || '';
  } while (pageToken);
  return videos;
}

